// The dark path: theft, smuggling, contracts, the Ghost Market, gambling dens, bounty hunters, prisons,
// framing, the Green Forest and the Water Fortress, the Blood Shadow Pavilion, and the cost of infamy.
// Written for a Teen rating: crimes resolve as rolls and consequences, never as method.
import { E, O, C, R, P, M, Q } from './kit.js';
import { template } from '../../engine/registry.js';

// A locked choice that is also rolled.
const QP = (t, req, p, ok, no) => ({ t, req, p, ok, no });
const QR = (t, req, stat, dc, ok, no) => ({ t, req, roll: { stat, dc }, ok, no });

// Anyone already walking the dark path.
const DARK = { or: [{ any: ['cr.thief', 'cr.gang', 'cr.burglar', 'cr.smuggler', 'cr.fence'] }, { faction: 'unorthodox' }, { career: ['bandit', 'assassin', 'informant'] }] };
const BLADE = { or: [{ sect: 'bloodshadow' }, { career: 'assassin' }] };

const handwritten = [
  // ── Hunger and small sins ───────────────────────────────────────
  E('cr_bun_theft', 'crime', { if: { age: [7, 15], wealth: '<=5' }, art: 'market', text: 'The steamed-bun seller has turned to shout at a dog. His tray is right there, still smoking, and you have not eaten since yesterday.', choices: [
    R('Take two and run', 'body', 12, O('You were three streets away before he noticed. They were the best thing you have ever stolen, and the first.', { health: 3, flag: 'cr.thief', infamy: 0.5 }), O('He caught you by the collar. He did not call the guard; he made you knead dough until dark, and then gave you a bun anyway.', { body: 1, sanity: 2 })),
    C('Ask him for the burnt ones', O('He looked at you for a long moment and handed over three burnt buns. "Come back tomorrow," he said. You did, for a year.', { health: 2, charm: 1 })),
    C('Walk away hungry', O('You walked away. Your stomach argued about it all night.', { health: -2, sanity: 1 })),
  ] }),
  E('cr_street_gang', 'crime', { if: { age: [10, 17], locType: 'city', not: ['cr.gang', 'cr.gang_left'] }, bind: { x: { ageRel: [1, 4], minAge: 12, role: 'acquaintance', aff: 40 } }, text: 'A gap-toothed kid called {x} has been watching you for a week. Today {x.he} sits down beside you. "The Rat Lane crew could use quick hands. We look after our own."', choices: [
    C('Join the Rat Lane crew', O('You swore an oath over a cracked bowl of rice wine you were too young to drink. {x} grinned. You belong to something now, for better or worse.', { flag: 'cr.gang', rel: { x: { aff: 15, role: 'friend' } }, infamy: 1 })),
    R('Ask what "look after" means', 'insight', 15, O('It meant paying a cut to a man called Fat Bong, who paid a cut to the constable. You declined. {x} looked almost relieved for you.', { insight: 1, rel: { x: { res: 10 } } }), O('{x} shrugged. "It means what it means." You said no and were not sure why.', { rel: { x: { aff: -5 } } })),
    C('Tell {x.him} to get lost', O('{x} spat and left. You saw {x.him} sometimes after that, thinner every year.', { rel: { x: { aff: -10 } } })),
  ] }),
  E('cr_gang_lookout', 'crime', { if: { flag: 'cr.gang', age: [11, 22] }, art: 'night', text: 'The crew is hitting a pawnshop tonight. Your job is to whistle if the night watch comes round the corner. Simple, they say. It is always simple, they say.', choices: [
    P('Keep watch', 0.7, O('The watch never came. Your share was more money than you had ever held.', { wealth: 12, infamy: 1, flag: 'cr.burglar' }), O('The watch came. You whistled. Everyone ran but the smallest, who was caught. Nobody says her name now.', { sanity: -6, infamy: 1, flag: 'cr.burglar' })),
    C('Whistle early, on purpose', O('You whistled at nothing. The crew scattered, the pawnshop slept, and the crew boss looked at you for a long time afterwards.', { flag: 'cr.gang_doubt', sanity: 2 })),
    C('Go inside with them', R('Go inside with them', 'body', 20, O('The strongbox was where everyone hides it, behind the ancestral tablets. The crew boss gave you a double share and a new nickname.', { wealth: 20, infamy: 2, flag: ['cr.burglar', 'cr.gang_trusted'] }), O('The pawnbroker was asleep in the shop. He woke up shouting, and the constables got a good look at your face.', { infamy: 3, flag: 'cr.burglar', next: 'cr_county_jail' }))),
  ] }),
  E('cr_gang_boss', 'crime', { if: { flag: 'cr.gang', age: [14, 26] }, text: 'Fat Bong, who runs Rat Lane from a teahouse he does not pay for, wants you to collect eight taels from a widow. "Take whatever she has," he says. "Make an impression."', choices: [
    C('Collect', O('She paid with her husband’s hairpin. You will remember her face longer than she remembers yours.', { wealth: 8, infamy: 2, sanity: -5, flag: 'cr.gang_trusted' })),
    Q('Pay it yourself (8 taels)', { wealth: '>=8' }, O('You paid Fat Bong from your own purse and told him she cried. He was satisfied. She never knew.', { wealth: -8, sanity: 4 })),
    C('Quit the crew', R('Quit the crew', 'charm', 22, O('You told Fat Bong you were done. He laughed and let you go, which was the most frightening thing he could have done.', { flag: 'cr.gang_left', unflag: 'cr.gang' }), O('Fat Bong did not like quitters. His men explained it to you in an alley.', { flag: 'cr.gang_left', unflag: 'cr.gang', injury: { name: 'cracked ribs', seasons: 3, sev: 10 } }))),
  ] }),
  E('cr_old_pickpocket', 'crime', { if: { age: [10, 30], locType: 'city' }, text: 'An old man with nine fingers does coin tricks for children by the bridge. Today he does one for you, and your own purse ends up in his hand. "Honest pockets," he says. "Shall I teach you dishonest fingers?"', choices: [
    C('Learn from him', O('He taught you all spring. "Never from the poor," he said. "Never from the alert. And never from me." You checked: your purse was gone again.', { body: 2, insight: 1, flag: 'cr.thief', infamy: 1 })),
    C('Ask how he lost the finger', O('"A Kaifeng magistrate kept it," he said, "as a souvenir." Then, because you had asked kindly, he told you how to get into the inner Ghost Market.', { flag: 'cr.gm_heard', codex: { id: 'secret.cr_ghost_word', cat: 'secrets', title: 'The Ghost Market’s door', text: 'To enter the inner Ghost Market in Kaifeng, knock three times on the fourth lantern post under the old north wall and say: "The moon owes me a debt."' } })),
    C('Walk on', O('"Honest pockets," he called after you, approvingly or not.')),
  ] }),
  E('cr_fence', 'crime', { if: { any: ['cr.thief', 'cr.burglar'], age: [14, 50], locType: 'city', not: 'cr.fence' }, bind: { x: { age: [40, 65], role: 'acquaintance', aff: 30, traits: ['greedy', 'cunning'] } }, text: 'The back room of a lacquer shop. {x} weighs a silver bracelet in one palm and you in the other. "I buy anything that is not on fire," {x.he} says. "And I forget faces for a modest fee."', choices: [
    C('Do business', O('{x} paid a third of what it was worth, which {x.he} called generous. It was. You have a fence now, and in your line a fence is worth more than a friend.', { wealth: 10, flag: 'cr.fence', rel: { x: { aff: 10 } } })),
    R('Haggle', 'charm', 25, O('You haggled {x.him} up to half. {x} looked at you with something like professional respect.', { wealth: 16, flag: 'cr.fence', rel: { x: { res: 15 } } }), O('{x} slid the bracelet back. "Come back when you are less sure of yourself."', { charm: 1 })),
    C('Leave the bracelet and go', O('You left it on the counter and walked out. Some doors only open one way.', { insight: 1, sanity: 2 })),
  ] }),
  E('cr_loan_shark', 'crime', { if: { age: [16, 60], wealth: '<=3', not: ['cr.debt', 'cr.debt_done'] }, text: 'A man in a fine coat finds you at your lowest. "Thirty taels," he says, "today, no questions. Forty-five at the end of the year. Everyone pays me back, one way or another."', choices: [
    C('Take the money', O('Thirty taels in a red envelope, like a wedding gift. You felt rich for almost a week.', { wealth: 30, flag: 'cr.debt', next: { id: 'cr_debt_due', in: 4 } })),
    C('Refuse', O('"Everyone refuses once," he said, and tipped his hat.')),
  ] }),
  E('cr_debt_due', 'crime', { on: 'scheduled', danger: true, text: 'The man in the fine coat is back, with two friends who do not wear coats at all. "Forty-five taels," he says pleasantly.', choices: [
    Q('Pay (45 taels)', { wealth: '>=45' }, O('You paid. He counted it twice and smiled. "A pleasure. Come again." You will not.', { wealth: -45, unflag: 'cr.debt', flag: 'cr.debt_done' })),
    C('Offer to work it off', O('"I have a boat that needs an extra pair of hands," he said. "Do not look in the crates." You did not look in the crates for a whole season. Debt cleared.', { unflag: 'cr.debt', flag: ['cr.smuggler', 'cr.debt_done'], infamy: 2 })),
    C('Fight his friends', O('His friends rolled their shoulders.', { combat: { foe: { name: 'the loan shark’s bruiser', kind: 'brawler', rel: 0 }, context: 'duel', lethal: 0.05, win: { text: 'The bruisers went down. The man in the fine coat tore up your note. "A business expense," he said, and left.', unflag: 'cr.debt', flag: 'cr.debt_done', infamy: 2 }, lose: { text: 'They took what you had, and the rest out of your hide. The debt is paid. You will feel it every winter.', unflag: 'cr.debt', flag: 'cr.debt_done', wealth: -20 } } })),
    R('Run', 'body', 25, O('You ran that night and kept running. Somewhere, a man in a fine coat has your name in a ledger.', { unflag: 'cr.debt', flag: ['cr.debt_fled', 'cr.debt_done'], infamy: 1 }), O('They caught you at the city gate and took it out of your purse and your pride.', { unflag: 'cr.debt', flag: 'cr.debt_done', wealth: -30, health: -10 })),
  ] }),

  // ── Framed, jailed ──────────────────────────────────────────────
  E('cr_framed_theft', 'crime', { if: { age: [14, 60], locType: 'city' }, art: 'inn', text: 'A jade seal has gone missing from the magistrate’s guest, and his servant points at you across the crowded inn. "That one. I saw that one by the stables."', choices: [
    R('Prove you were elsewhere', 'insight', 25, O('You named three people who saw you at the noodle stall, and the noodle seller backed you with real indignation. The seal turned up in the servant’s own sleeve.', { fame: 1, insight: 1 }), O('Your alibi was a noodle seller who could not remember you. The constables took you away.', { infamy: 2, flag: 'cr.framed', next: 'cr_county_jail' })),
    Q('Grease the constable (15 taels)', { wealth: '>=15' }, O('Fifteen taels helped the constable remember another suspect. You hope it was the servant.', { wealth: -15, sanity: -2 })),
    C('Run', R('Run', 'body', 22, O('You were over the stable wall before anyone thought to stop you. Now there is a poster of you captioned "jade thief." You did not even get the jade.', { infamy: 4, flag: 'cr.framed' }), O('You made it to the stable wall and no further.', { infamy: 3, flag: 'cr.framed', next: 'cr_county_jail' }))),
  ] }),
  E('cr_county_jail', 'crime', { on: 'scheduled', art: 'prison', title: 'The county jail', text: 'The cell smells of old straw and older worry. Your cellmates are a debtor, a drunk, and a very calm old woman who says she was a Dang family servant for forty years.', choices: [
    Q('Bribe the jailer (20 taels)', { wealth: '>=20' }, O('Twenty taels found a clerical error in your case. You walked out at dawn, poorer and wiser.', { wealth: -20, flag: 'cr.jailbird' })),
    R('Plead at the hearing', 'charm', 25, O('The magistrate was hungover and wanted to go home. "Insufficient evidence," he said, and waved you out.', { flag: 'cr.jailbird' }), O('The magistrate gave you a season hauling stone on the city walls. You got stronger, and hated every stone.', { flag: 'cr.jailbird', body: 2, health: -8, infamy: 2 })),
    C('Listen to the old woman', O('Her name was Old Lady Bok. She talked all season about the Dang manor: which courtyards the family never enters, and why the matriarch’s second son is always so polite at tea. They let you out in spring.', { flag: 'cr.jailbird', insight: 2, codex: { id: 'secret.cr_dang_servant', cat: 'people', title: 'Old Lady Bok', text: 'A former Dang servant in a county jail said the matriarch’s second son, Dang Gwang, has been too polite at tea for years, and that the matriarch never drinks first.' } })),
  ] }),
  E('cr_impostor', 'crime', { if: { age: [18, 70], stat: { fame: '>=15' } }, text: 'In three towns now, someone using your name has run up debts, insulted a magistrate and made promises to a widow. The posters are going up.', choices: [
    R('Hunt the impostor down', 'insight', 30, O('You found the impostor, a hungry young actor with your walk down perfectly. He wept. You made him pay the debts back in public, in your name.', { fame: 3, flag: 'cr.impostor_caught', next: { id: 'cr_impostor_after', in: 6 } }), O('The trail went cold in a riverside town. Your name went on without you.', { infamy: 4 })),
    C('Let it run', O('You let it run. By the end of the year your reputation was half yours and half a stranger’s.', { infamy: 3, fame: 1 })),
  ] }),
  E('cr_impostor_after', 'crime', { on: 'scheduled', text: 'A letter in a careful hand: the actor who once used your name now runs a small troupe. They perform a play about you. In it, you are taller.', fmt: 'letter', fx: { fame: 2, sanity: 3 } }),

  // ── The Ghost Market ────────────────────────────────────────────
  E('cr_ghost_invite', 'crime', { if: { any: ['cr.fence', 'cr.gm_heard', 'cr.smuggler'], age: [16, 60], notLoc: 'kaifeng' }, text: 'Word comes through the usual channels: a buyer in Kaifeng’s Ghost Market pays triple for anything with a sect seal on it. A grain barge leaves tomorrow.', choices: [
    C('Take the barge to Kaifeng', O('Three days on a grain barge, then the canals of Kaifeng, and lanterns under the old wall.', { travel: 'kaifeng' })),
    C('Stay where you are', O('You stayed. Triple is a number that gets people hurt.')),
  ] }),
  E('cr_ghost_door', 'crime', { if: { loc: 'kaifeng', age: [14, 90], not: 'cr.gm_token' }, art: 'night', title: 'The inner market', text: 'Under Kaifeng’s old north wall the Ghost Market sells cheap knives and fake elixirs to visitors. Everyone knows there is an inner market. Nobody will tell you how to get in.', choices: [
    M('Knock three times on the fourth lantern post', 'secret.cr_ghost_word', O('You knocked and said the words. A door that was not there opened in the wall. The doorkeeper studied you with real curiosity. "Who told you that? Never mind. Welcome."', { flag: 'cr.gm_token' })),
    Q('Buy a lantern token (30 taels)', { wealth: '>=30' }, O('A pockmarked tout sold you a paper lantern token. It worked, which surprised you both.', { wealth: -30, flag: 'cr.gm_token' })),
    R('Follow someone who belongs', 'insight', 30, O('You followed a woman with ink-stained fingers to the fourth lantern post, watched her knock, and listened.', { flag: 'cr.gm_token', codex: 'secret.cr_ghost_word' }), O('The man you followed turned in an alley and asked, very politely, why. You had no good answer.', { health: -5 })),
    C('Buy a candied plum and leave', O('The candied plums are the only honest thing in the Ghost Market.', { sanity: 1 })),
  ] }),
  E('cr_ghost_inner', 'crime', { if: { flag: 'cr.gm_token', loc: 'kaifeng', age: [14, 90] }, once: false, cd: 3, art: 'market', text: 'Inside the wall the Ghost Market drops its manners. A pill-seller offers Marrow-Cleansing Pills at a third of the guild price. A scroll-seller keeps a cloth over something he will not name.', choices: [
    QP('Buy the cheap pills (20 taels)', { wealth: '>=20' }, 0.5, O('They were real, fallen off a Shaolin cart. You felt your marrow burn clean.', { wealth: -20, item: { marrow_pill: 1 } }), O('Chalk and honey, and something that made you sick for a week. The seller’s stall was gone by morning.', { wealth: -20, health: -12 })),
    Q('Lift the cloth (60 taels)', { wealth: '>=60', noManual: 'uno_silent_needle' }, O('A Blood Shadow manual, still smelling of the Pavilion’s incense. Somewhere in Kaifeng, someone has noticed it is gone.', { wealth: -60, manual: 'uno_silent_needle', infamy: 2, flag: 'cr.pavilion_scroll' })),
    R('Sell a rumour', 'charm', 25, O('A secret-seller paid fifteen taels for a rumour you half believed. She seemed to believe all of it.', { wealth: 15 }), O('They paid you in counterfeit silver. Even here, that is considered rude.', { sanity: -1 })),
    C('Just walk the stalls', O('A one-eyed woman sold you a map of Kaifeng’s sewers "for when you need it." You hope you never do.', { insight: 1, wealth: -1 })),
  ] }),
  E('cr_ghost_auction', 'crime', { if: { flag: 'cr.gm_token', loc: 'kaifeng', age: [18, 90] }, art: 'night', title: 'The cistern auction', text: 'Once a year the inner market holds an auction in a drained cistern. Tonight’s last lot is a single wax-sealed pill: a Small Reincarnation Pill, stolen from Shaolin, the auctioneer says, "with the receipt."', choices: [
    Q('Bid everything (300 taels)', { wealth: '>=300' }, O('You won. Three people in the cistern watched you leave with very still faces.', { wealth: -300, item: { reincarnation_pill: 1 }, infamy: 2, rep: { orthodox: -5 }, next: { id: 'cr_ghost_followed', in: 1 } })),
    R('Watch who bids, and why', 'insight', 35, O('The winner was an Eastern Depot eunuch in a merchant’s hat. Someone wants the Depot to hold a Shaolin treasure, and Shaolin to know it.', { codex: { id: 'secret.cr_depot_pill', cat: 'secrets', title: 'The pill at the auction', text: 'At the Ghost Market’s cistern auction, a Small Reincarnation Pill stolen from Shaolin was bought by an Eastern Depot eunuch in disguise. The Depot collects murim treasures, and murim grudges.' } }), O('You watched a great deal of money change hands and understood none of it.', { insight: 1 })),
    C('Leave before the last lot', O('You left early. Auctions in cisterns end one of two ways, and you did not want to see either.')),
  ] }),
  E('cr_ghost_followed', 'crime', { on: 'scheduled', danger: true, art: 'night', text: 'Two shadows have followed you since the cistern. In a quiet lane by the canal they stop pretending.', choices: [
    C('Turn and fight', O('You turned.', { combat: { foe: { name: 'a Ghost Market cutthroat', kind: 'assassin', rel: 0, key: 'cr_cutthroat' }, context: 'ambush', lethal: 0.2, win: { text: 'They fled into the canal. You kept the pill and lost your taste for auctions.', fame: 1 }, lose: { text: 'They took the pill and left you in the canal, alive, which in Kaifeng counts as courtesy.', take: { reincarnation_pill: 1 } } } })),
    R('Lose them in the lanes', 'body', 35, O('Kaifeng has more lanes than people. You used most of them.', { body: 1 }), O('They were better at lanes than you. You bought your life with the pill.', { take: { reincarnation_pill: 1 }, sanity: -3 })),
    M('Lead them to the sewer map’s dead end', 'foe.cr_cutthroat', O('You remembered how these two moved, from another life. You walked them into the dead end and walked out alone.', { insight: 2 })),
  ] }),
  E('cr_madam_yeon', 'crime', { if: { loc: 'kaifeng', age: [16, 80] }, art: 'inn', text: 'The Thousand Ears Pavilion is a teahouse where nobody drinks the tea. {@madam_yeon} pours you a cup anyway. "Everyone comes to me eventually," she says. "Buying, or selling?"', choices: [
    Q('Buy a secret (40 taels)', { wealth: '>=40' }, O('She sold you a name: the steward who books the Pavilion’s contracts for a Great Family. "Do not tell them where you heard it," she said, meaning that you would.', { wealth: -40, meet: '@madam_yeon', codex: { id: 'secret.cr_jegal_steward', cat: 'secrets', title: 'The Jegal steward', text: 'Madam Yeon says a Jegal steward named Pyeon Su places the Jegal family’s contracts with the Blood Shadow Pavilion through a Kaifeng teahouse called the Willow Leaf.' } })),
    R('Sell her something true', 'insight', 28, O('You told her something about your own sect that nobody else knew. She paid well, and looked at you like an investment.', { wealth: 25, meet: '@madam_yeon', rel: { '@madam_yeon': { res: 10 } }, infamy: 1 }), O('She already knew it. "Sweet of you," she said, and charged you for the tea.', { wealth: -2, meet: '@madam_yeon' })),
    C('Drink the tea and leave', O('The tea was excellent. You suspect the bill included the conversation you did not have.', { meet: '@madam_yeon', wealth: -1 })),
  ] }),

  // ── The Blood Shadow Pavilion ───────────────────────────────────
  E('cr_pavilion_invite', 'crime', { if: { age: [16, 40], sect: 'none', or: [{ stat: { infamy: '>=15' } }, { career: 'assassin' }] }, art: 'letter', fmt: 'letter', text: 'A folded paper in your boot, where nobody could have put it: "The Blood Shadow Pavilion has watched you. Kaifeng, the Willow Leaf teahouse, any night. Come alone. Come quietly."', choices: [
    C('Go to Kaifeng', O('The Willow Leaf served you a cup with a black thread tied around it. By dawn you had sworn yourself to the Pavilion, and been given a name that is not yours.', { travel: 'kaifeng', join: 'bloodshadow', infamy: 3, rep: { orthodox: -5 } })),
    C('Burn the note', O('You burned it. The next morning, a second note in your boot said only: "Understood."', { sanity: -2 })),
  ] }),
  E('cr_pavilion_first', 'crime', { if: { sect: 'bloodshadow', rank: 0, not: 'cr.first_contract' }, art: 'night', title: 'The first contract', text: 'Your first contract: a county magistrate who sells grain meant for the starving. The Pavilion hands you a slip of paper and does not ask whether you can.', choices: [
    R('Carry it out', 'body', 25, O('It was done before the second watch. You did not sleep that night, or the next. The grain reached the villages within a month.', { flag: ['cr.first_contract', 'cr.kills+1'], merit: 12, wealth: 20, infamy: 4, sanity: -8 }), O('You lost your nerve at the last wall and came back empty-handed. The Pavilion said nothing, which was its own kind of verdict.', { flag: 'cr.first_contract', merit: -5, sanity: -2 })),
    C('Leave proof of his crimes for the prefect instead', O('You left his ledgers on the prefect’s desk with a black thread around them. He was dismissed and fled. The Pavilion was annoyed, and slightly impressed.', { flag: 'cr.first_contract', merit: 4, fame: 2 })),
    C('Refuse the contract', O('"A contract refused is a contract broken," your handler said. "Remember that." You will.', { flag: ['cr.first_contract', 'cr.broke_contract'], merit: -10 })),
  ] }),
  E('cr_nameless', 'crime', { if: { sect: 'bloodshadow', rank: '>=1', alive: 'nameless' }, art: 'moon', text: 'On a roof above Kaifeng, a woman you have never seen before sits down beside you. Every Blood Shadow knows that this means {@nameless} has come to look at them. "Why do you do this work?" she asks.', choices: [
    C('"For the money."', O('"Honest," she said. "Honest people live longer here." She was gone before you turned.', { meet: '@nameless', rel: { '@nameless': { res: 5 } }, merit: 5 })),
    C('"Because some people deserve it."', O('"Everyone thinks that," she said. "The ledger disagrees." She told you she has never taken a contract on a child, and that she tears up any contract whose client lied.', { meet: '@nameless', rel: { '@nameless': { res: 10 } }, codex: { id: 'secret.cr_nameless_ledger', cat: 'people', title: 'Nameless’s ledger', text: 'Nameless, Master of the Blood Shadow Pavilion, keeps a ledger of every contract. She never accepts a contract on a child, and she voids any contract whose client lied to the Pavilion.' } })),
    C('"Because nobody else would have me."', O('She was quiet for a while. "That is why I started," she said. It was the only personal thing anyone has ever heard her say.', { meet: '@nameless', rel: { '@nameless': { aff: 15 } }, sanity: 3 })),
  ] }),
  E('cr_pavilion_namgung', 'crime', { if: { sect: 'bloodshadow', year: [20, 23], alive: 'namgung_hwi' }, danger: true, art: 'night', title: 'A contract on a patriarch', text: 'The Pavilion has taken the largest contract in a decade: Namgung Hwi, patriarch of the Namgung, in his own study. The client is anonymous. You are on the team.', choices: [
    C('Do your part', O('You held the outer wall while others went over the roof. Whatever happened in that study, you were part of it.', { merit: 25, wealth: 60, infamy: 8, sanity: -10, flag: 'cr.namgung_team' })),
    M('Tell Nameless the client lied about who they are', 'secret.cr_jegal_steward', O('You told her the contract came from a Jegal steward posing as a Namgung rival. She checked. By the Pavilion’s own rule, the contract was void. Namgung Hwi lived and never knew why.', { avert: 'namgung_assassination', merit: 15, gaze: 1, rel: { '@nameless': { res: 20 } } })),
    C('Warn the Namgung anonymously', P('Warn the Namgung anonymously', 0.5, O('A note on the patriarch’s desk, a black thread around it. The Namgung doubled their guards that winter. The Pavilion never learned who did it.', { avert: 'namgung_assassination', gaze: 1, sanity: 4 }), O('The note arrived. So did the Pavilion’s questions, and they found you.', { flag: 'cr.broke_contract', merit: -20, infamy: 2 }))),
    C('Ask to be left off the team', O('You were left off. The Pavilion noted your reluctance in a ledger somewhere.', { merit: -5 })),
  ] }),
  E('cr_pavilion_reckoning', 'crime', { if: { flag: 'cr.broke_contract', age: [16, 80] }, danger: true, art: 'night', text: 'Every Blood Shadow knows the rule: a broken contract is paid for. Tonight a figure in grey waits at the foot of your bed, patient as a heron.', choices: [
    C('Fight for your life', O('You rolled off the bed with a blade already in your hand.', { combat: { foe: { name: 'a Silent Shadow of the Pavilion', kind: 'assassin', rel: 0.5, key: 'cr_silent_shadow' }, context: 'assassination', lethal: 0.3, win: { text: 'The grey figure fell back through the window. A black thread was left on your pillow: the debt is paid, this once.', unflag: 'cr.broke_contract', fame: 2 }, lose: { text: 'You woke at dawn with a shallow cut across your throat that someone chose not to deepen. The debt is paid. The message is received.', unflag: 'cr.broke_contract', sanity: -10 } } })),
    QP('Pay the forfeit (100 taels)', { wealth: '>=100' }, 0.85, O('You laid a hundred taels on the table. The figure counted it without looking and was gone.', { wealth: -100, unflag: 'cr.broke_contract' }), O('The figure took the money and left a black thread anyway. It is not over.', { wealth: -100 })),
    R('Talk', 'charm', 40, O('You talked about the ledger and the client who lied. The figure listened, nodded once, and left the window open behind it.', { unflag: 'cr.broke_contract', insight: 1 }), O('The figure was not there to listen.', { combat: { foe: { name: 'a Silent Shadow of the Pavilion', kind: 'assassin', rel: 0.5, key: 'cr_silent_shadow' }, context: 'assassination', lethal: 0.3, win: { text: 'You drove it off. The debt is paid, this once.', unflag: 'cr.broke_contract' }, lose: { text: 'You woke with a warning cut and an empty purse. The debt is paid.', unflag: 'cr.broke_contract', wealth: -30 } } })),
  ] }),

  // ── The Green Forest ────────────────────────────────────────────
  E('cr_gf_granary', 'crime', { if: { sect: 'greenforest', flag: 'w.famine' }, art: 'fire', text: 'The famine has the county starving while the magistrate’s granary is full to the rafters. Your captain wants to empty it tonight. He has not said who will get the grain.', choices: [
    C('Empty it and give the grain away', O('You hauled sacks until dawn and left them in village squares. The captain cursed you, then the villagers cheered him, and he stopped cursing.', { merit: 8, fame: 4, infamy: 2, rep: { court: -5 } })),
    C('Empty it and sell the grain', O('You sold it back to the starving at famine prices. The stronghold ate well that winter. You did not.', { merit: 10, wealth: 30, infamy: 5, sanity: -8 })),
    C('Tip off the magistrate', O('The magistrate was waiting. The raid failed, three brothers were taken, and the magistrate kept every grain. Nobody knows it was you.', { merit: -15, rep: { court: 5 }, sanity: -10 })),
  ] }),
  E('cr_gf_oath', 'crime', { if: { sect: 'greenforest', age: [16, 60], realm: '>=1' }, bind: { x: { ageRel: [-3, 6], role: 'acquaintance', aff: 45, res: 40, realm: [1, 3], sect: 'greenforest' } }, art: 'feast', text: 'At the stronghold’s autumn feast a bandit captain named {x} slams a cup down beside yours. "You held the pass with me," {x.he} says. "Swear brotherhood with me under Heaven, and no one in the Green Forest touches you."', choices: [
    C('Swear the oath', O('You cut your palms and mixed the blood in the wine. The whole hall roared. {x} has not stopped grinning since.', { rel: { x: { aff: 25, res: 10, role: 'sworn' } }, achieve: 'sworn', merit: 5 })),
    C('Drink with {x.him}, but swear nothing', O('You drank until the stars spun. {x} was disappointed but not offended. "Next year," {x.he} said.', { rel: { x: { aff: 8 } } })),
  ] }),
  E('cr_gf_bloodblade', 'crime', { if: { sect: 'greenforest', year: [11, 15], alive: 'blood_blade', not: 'cr.bb_spoke' }, art: 'fire', text: '{@blood_blade} is boasting in the stronghold: come autumn he will ride south and burn a village under Mount Hua "to see the plum monks run." His men laugh too loudly.', choices: [
    M('Tell the Mountain Tiger exactly where and when', 'timeline.willow_raid', O('You named the village, the season and the road. {@mountain_tiger} went very quiet, then broke a table. "The Green Forest robs. It does not burn children." Pi Mun was sent north in chains, and Willow Creek’s autumn was quiet.', { flag: 'cr.bb_spoke', avert: 'willow_raid', merit: 15, gaze: 1, meet: '@mountain_tiger', rel: { '@mountain_tiger': { res: 20 } } })),
    C('Report the boast to the Mountain Tiger', P('Report the boast to the Mountain Tiger', 0.35, O('{@mountain_tiger} believed you and forbade it. Pi Mun sulked all winter, and the raid never rode.', { flag: 'cr.bb_spoke', avert: 'willow_raid', merit: 10, meet: '@mountain_tiger' }), O('"Pi Mun boasts like other men breathe," the Mountain Tiger said. He did nothing. Pi Mun heard who had spoken.', { flag: 'cr.bb_spoke', meet: '@mountain_tiger', rel: { '@blood_blade': { aff: -30 } } }))),
    C('Say nothing', O('You said nothing. It is not your village. You tell yourself that often.', { flag: 'cr.bb_spoke', sanity: -4 })),
  ] }),

  // ── The Water Fortress ──────────────────────────────────────────
  E('cr_wf_join', 'crime', { if: { loc: 'dongting', sect: 'none', age: [14, 40] }, art: 'lake', text: 'A reed boat bumps against your ferry. The pirate in it has arms like ship’s ropes. "The Water Fortress takes anyone who can swim to the third island and back," she says. "Most cannot."', choices: [
    R('Swim', 'body', 24, O('You crawled onto the beach after dark, coughing up half the lake. The pirate handed you a dry jacket. "Brother," she said.', { join: 'waterfortress', infamy: 3, rep: { unorthodox: 8 } }), O('A fishing boat pulled you out halfway, blue-lipped. The pirate laughed, not unkindly.', { health: -10 })),
    C('Decline', O('"Your loss," she said, and paddled off into the reeds.')),
  ] }),
  E('cr_wf_refugees', 'crime', { if: { sect: 'waterfortress', age: [14, 70] }, art: 'river', text: 'You are collecting the Fortress’s toll on the river when a boat comes through riding low: refugees from the flood, every one of them, and not a coin among them.', choices: [
    C('Let them through free', O('You waved them on. An old man bowed to you from the stern until the boat went round the bend.', { merit: -3, fame: 2, sanity: 4 })),
    C('Take the toll in goods', O('You took their pots, a cart wheel and a wedding quilt. The Fortress books balanced.', { merit: 6, wealth: 6, infamy: 2, sanity: -6 })),
    Q('Pay their toll yourself (10 taels)', { wealth: '>=10' }, O('You paid from your own purse. The quartermaster raised an eyebrow and wrote it down without comment.', { wealth: -10, merit: 2, sanity: 5 })),
  ] }),
  E('cr_wf_grain_fleet', 'crime', { if: { sect: 'waterfortress', year: [12, 13] }, danger: true, art: 'ship', title: 'The grain fleet', text: 'Gyeong Pa has decided to sink an imperial grain fleet on the Great River, "to remind the court whose river it is." Every boat in the Fortress is going.', choices: [
    C('Go with the boats', P('Go with the boats', 0.7, O('Fire on the water and grain bobbing in the current like yellow lilies. The court swore vengeance. The Fortress drank for a week.', { merit: 20, infamy: 6, rep: { court: -15 }, wealth: 25 }), O('An imperial archer found you in the smoke. You were fished out of the river by your own side.', { merit: 10, infamy: 4, injury: { name: 'arrow wound', seasons: 4, sev: 15 } }))),
    C('Volunteer to guard the Fortress instead', O('You guarded empty docks while the river burned. The quartermaster called it cowardice and paid you anyway.', { merit: 2 })),
    C('Slip a warning to the fleet', O('A fisherman carried your note. The fleet changed course at Wuchang. Gyeong Pa searched the Fortress for a traitor for a month, and never looked at you.', { rep: { court: 8 }, merit: -5, sanity: -2, flag: 'cr.wf_traitor' })),
  ] }),
  E('cr_wf_envoy', 'crime', { if: { sect: 'waterfortress', rank: '>=1', alive: 'water_lord' }, art: 'lake', text: '{@water_lord} wants someone to sit across a table from a court envoy and negotiate the price of not sinking the next grain fleet. "You have a trustworthy face," he says. "It is wasted on us."', choices: [
    R('Negotiate', 'charm', 32, O('You got the court to pay a "river maintenance fee" twice the old toll and call it a victory. Gyeong Pa laughed until he coughed.', { merit: 20, wealth: 20, meet: '@water_lord', rel: { '@water_lord': { res: 20 } } }), O('The envoy left insulted, and the court sent soldiers instead of silver.', { merit: -5, meet: '@water_lord' })),
    C('Decline the honour', O('"A trustworthy face and no ambition," Gyeong Pa sighed. "Wasted twice."', { meet: '@water_lord' })),
  ] }),

  // ── Bounties and infamy ─────────────────────────────────────────
  E('cr_bounty_posted', 'crime', { if: { age: [16, 90], stat: { infamy: '>=30' }, not: 'cr.bounty' }, art: 'city', text: 'The Murim Alliance has posted a bounty on you: two hundred taels, alive, one hundred otherwise. Someone has helpfully added a portrait. Your nose is wrong.', choices: [
    C('Read it twice and walk on', O('You walked on. From now on, every stranger in every inn is a question.', { flag: 'cr.bounty', sanity: -4 })),
    C('Tear it down and leave your mark', O('You tore it down and left a note: "Two hundred is an insult." The bounty went up the next month.', { flag: 'cr.bounty', infamy: 3, fame: 1 })),
  ] }),
  E('cr_infamy_children', 'crime', { if: { age: [20, 120], stat: { infamy: '>=50' } }, art: 'road', text: 'In a village where you stop for water, a mother calls her children inside and bars the door. Through the shutters you hear her: "Behave, or {name} will take you."', choices: [
    C('Leave a coin on the step', O('You left a coin on the step and went on. When you looked back, the coin was gone and the door was still barred.', { wealth: -1, sanity: -2 })),
    C('Laugh', O('You laughed. It echoed in the empty street longer than it should have.', { infamy: 1, sanity: -4 })),
    C('Knock and ask for water anyway', R('Knock and ask for water anyway', 'charm', 45, O('She gave you water with shaking hands. Her youngest peeked out and asked if you were really that one. You said no. It was almost true.', { sanity: 3 }), O('Nobody opened. You drank from the horse trough.', { sanity: -2 }))),
  ] }),
  E('cr_infamy_inn', 'crime', { if: { age: [18, 120], stat: { infamy: '>=35' }, locType: ['city', 'village'] }, once: false, cd: 4, art: 'inn', text: 'The innkeeper recognises you and goes white. "No charge," he says quickly. "For you, no charge. Ever."', choices: [
    C('Accept', O('You ate for free. The food was good. Nobody sat within three tables of you.', { wealth: 3, infamy: 1, sanity: -2 })),
    C('Insist on paying', O('You put silver on the counter and refused to take it back. He looked at you as if you had spoken in a foreign language.', { wealth: -3, sanity: 2 })),
  ] }),
  E('cr_infamy_letter', 'crime', { if: { age: [18, 80], stat: { infamy: '>=30' }, has: 'parent' }, bind: { x: 'parent' }, fmt: 'letter', from: 'x', art: 'letter', text: 'A letter from {x}: "People say things about you in the market. I tell them they are wrong. Please write back and tell me they are wrong."', choices: [
    C('Write back the truth', O('You wrote the truth. The next letter took a long time to come. It said, "Eat properly. Come home if you can."', { rel: { x: { aff: -5, res: 5 } }, sanity: 2 })),
    C('Write back a kind lie', O('You wrote that they were wrong. {x} framed the letter. You have never felt worse holding a brush.', { rel: { x: { aff: 5 } }, sanity: -5 })),
    C('Do not write back', O('You did not write back. The letters kept coming, one a season, and then less.', { rel: { x: { aff: -12 } }, sanity: -3 })),
  ] }),
  E('cr_assassin_night', 'crime', { if: { age: [18, 100], realm: '>=2', or: [{ stat: { infamy: '>=40' } }, { stat: { fame: '>=50' } }] }, once: false, cd: 8, danger: true, art: 'night', text: 'You wake because the crickets have stopped. Someone is on your roof, very carefully not making a sound.', choices: [
    C('Meet them on the roof', O('You went up through the skylight.', { combat: { foe: { name: 'a hired blade', kind: 'assassin', rel: 0, key: 'cr_hired_blade' }, context: 'assassination', lethal: 0.25, win: { text: 'The assassin fled across the rooftops. In the gutter you found a contract slip with your name and a very insulting price.', fame: 2, infamy: 1 }, lose: { text: 'You woke on the roof tiles at dawn, with a warning cut and your purse gone.', wealth: -20 } } })),
    R('Leave by the back and let them find an empty bed', 'insight', 35, O('You stuffed your quilt with straw and watched from the woodshed as a blade went into it. You left that town by noon.', { insight: 1 }), O('They were waiting at the back. They had done this before.', { health: -15, wealth: -10 })),
    C('Call out to them', O('"The tea is still warm," you said to the ceiling. A long pause. Then soft footsteps, going away.', { charm: 1, sanity: -2 })),
  ] }),

  // ── Redemption and its price ────────────────────────────────────
  E('cr_repent_monk', 'crime', { if: { age: [20, 90], stat: { infamy: '>=20' }, not: 'cr.repent' }, art: 'temple', text: 'A Shaolin monk on pilgrimage shares your fire and says nothing about the posters. In the morning he says, "Shaolin has a field that needs ploughing, and nobody there asks a ploughman his name."', choices: [
    C('Go with him and plough', O('You ploughed Shaolin’s field for a year. Nobody asked your name. At the end of it you could sleep through the night again.', { flag: 'cr.repent', infamy: -10, sanity: 10, body: 2, rep: { orthodox: 5 } })),
    C('Thank him and stay on your road', O('He nodded as if he had expected that. "The field will still be there," he said.')),
  ] }),
  E('cr_restitution', 'crime', { if: { age: [20, 90], or: [{ flag: 'cr.repent' }, { stat: { infamy: '>=15' } }], any: ['cr.thief', 'cr.burglar', 'cr.kills', 'cr.first_contract'], not: 'cr.restitution' }, text: 'You cannot unstrike a blow or unsteal a purse. But you remember the faces, and some of them are still alive.', choices: [
    Q('Pay back what you can (60 taels)', { wealth: '>=60' }, O('You went door to door with silver and no explanations. One old woman threw it back at you. The others took it, and something in your chest unclenched.', { wealth: -60, infamy: -8, sanity: 8, flag: 'cr.restitution' })),
    C('Work for the ones you wronged', O('You mended roofs and dug ditches for a season in places where people knew why. Nobody thanked you. That was the point.', { infamy: -5, sanity: 5, body: 1, flag: 'cr.restitution' })),
    C('Decide the past is the past', O('The past disagreed, mostly at night.', { sanity: -3 })),
  ] }),
  E('cr_rejected_sect', 'crime', { if: { age: [15, 30], sect: 'none', stat: { infamy: '>=40' } }, art: 'temple', text: 'You kneel at the gate of an Orthodox sect. The gatekeeper knows your name, and the gate stays closed. "The righteous path is not for everyone," he says, without unkindness.', choices: [
    C('Keep kneeling', R('Keep kneeling', 'sanity', 60, O('You knelt nine days in the rain. On the tenth, an elder came out with an umbrella and said, "No. But I will remember you knelt." It was not nothing.', { infamy: -5, fame: 2, rep: { orthodox: 5 } }), O('You knelt until your knees gave out. The gate never opened.', { health: -10, sanity: -5 }))),
    C('Get up and go', O('You got up and went. The gatekeeper watched you all the way down the steps.', { sanity: -2 })),
  ] }),
  E('cr_last_job', 'crime', { if: { age: [35, 80], stat: { infamy: '>=25' }, flag: 'cr.restitution' }, art: 'inn', text: 'An old partner from your worst years finds you mending nets. One last job, they say. Enough silver to never mend another net.', choices: [
    C('Refuse', O('You refused. They called you soft. You went back to the net, and your hands did not shake.', { sanity: 6, infamy: -3 })),
    C('Take the job', P('Take the job', 0.5, O('It went perfectly. You bought a house with the silver and never felt at home in it.', { wealth: 80, infamy: 6, sanity: -8, unflag: 'cr.restitution' }), O('It went badly. Your partner ran, and the constables found you sitting on the bank, almost relieved.', { infamy: 6, unflag: 'cr.restitution', next: 'cr_county_jail' }))),
  ] }),

  // ── Careers of the dark path (the Work activity) ───────────────
  E('cr_work_bandit', 'crime', { on: 'work', if: { career: 'bandit' }, once: false, cd: 2, art: 'road', text: 'A lone merchant on a donkey, on your stretch of road, singing badly.', choices: [
    C('Take his purse', O('He handed it over and kept singing, slightly worse.', { wealth: 6, infamy: 1, careerUp: 1 })),
    C('Take a toll and give him directions', O('You took a tael and told him which road the real bandits used. He thanked you sincerely.', { wealth: 1, fame: 0.5 })),
    C('Let him pass and teach him a better song', O('Your fellow bandits will never let you forget this.', { sanity: 2, charm: 1 })),
  ] }),
  E('cr_work_informant', 'crime', { on: 'work', if: { career: 'informant' }, once: false, cd: 2, art: 'inn', text: 'You have overheard something worth selling: a sect elder’s gambling debts. Two buyers are interested. One is his rival. The other is his wife.', choices: [
    C('Sell to the rival', O('The rival paid well. The elder was quietly removed from his post by spring.', { wealth: 15, infamy: 1, careerUp: 2 })),
    C('Sell to the wife', O('The wife paid less, and the elder paid his debts very quickly after that.', { wealth: 8, careerUp: 1, sanity: 1 })),
    C('Sell it back to the elder', R('Sell it back to the elder', 'charm', 30, O('He paid twice what it was worth, and now owes you a favour he hates.', { wealth: 25, infamy: 2, careerUp: 2 }), O('He paid, and then sent two men to ask where else you had sold it.', { wealth: 10, health: -10 }))),
  ] }),
  E('cr_work_assassin', 'crime', { on: 'work', if: { career: 'assassin' }, once: false, cd: 3, art: 'night', text: 'The broker slides a slip across the table. A name, a town, a price. Below it, in a smaller hand: "Client prefers it look like illness."', choices: [
    R('Take the contract', 'insight', 30, O('It was done, and the town mourned a man of illness. You were paid, and you did not attend the funeral.', { wealth: 25, infamy: 3, sanity: -6, careerUp: 3, flag: 'cr.kills+1' }), O('The mark’s physician was sharper than expected, and asked questions. You left town with your fee unpaid.', { infamy: 2, careerUp: 1 })),
    C('Ask who the client is', O('The broker smiled. "Someone who will hire someone else if you keep asking." You took the next slip instead.', { insight: 1 })),
    C('Turn it down', O('You turned it down. The broker shrugged; there are always more slips.', { sanity: 2 })),
  ] }),

  // ── Corruption, poison, and other people’s crimes ───────────────
  E('cr_magistrate_squeeze', 'crime', { if: { age: [18, 70], locType: 'city', wealth: '>=30' }, text: 'The county magistrate has discovered that your papers are "irregular." He is sure the irregularity can be corrected, for a fee proportional to your evident prosperity.', choices: [
    C('Pay the fee', O('You paid. Your papers were corrected. You suspect they will become irregular again next year.', { wealth: -20 })),
    R('Find out what he is hiding', 'insight', 32, O('A clerk sold you the magistrate’s second ledger for the price of a dinner. The magistrate tore up his complaint against you with his own hands.', { flag: 'cr.magistrate_owes', insight: 1 }), O('The clerk you asked went straight to the magistrate. The fee doubled.', { wealth: -30 })),
    C('Refuse', O('You refused. A week later your lodging was searched, twice, and "evidence" was found, once.', { infamy: 2, next: 'cr_county_jail' })),
  ] }),
  E('cr_poison_plea', 'crime', { if: { age: [20, 80], or: [{ path: 'poison' }, { sect: 'dang' }, { career: 'physician' }] }, text: 'A woman with a bruise she keeps turning away from you asks, very quietly, whether you sell "something for a husband." She has brought all her savings in a handkerchief.', choices: [
    C('Refuse, and send her to the magistrate', O('She laughed at the word magistrate, and left. You never learned what became of her.', { sanity: -4 })),
    C('Give her a sleeping draught, and a plan', O('You gave her a harmless draught and the name of a nunnery in Emei that takes in runaway wives. She went that night, with her savings.', { sanity: 6, fame: 1 })),
    C('Go and have a word with the husband', R('Go and have a word with the husband', 'power', 25, O('You had a word with him. Afterwards he could not lift a cup without his hands shaking, and he never lifted one against her again.', { infamy: 2, sanity: 3 }), O('He had friends. You had a bad night.', { health: -12 }))),
  ] }),
  E('cr_poisoned_well', 'crime', { if: { age: [16, 80], realm: '>=1', locType: ['village', 'city'] }, danger: true, art: 'night', text: 'At midnight a man in a black-dyed hood is kneeling at the town well with a clay jar. When he sees you, he does not run. He smiles.', choices: [
    C('Stop him', O('You lunged for the jar.', { combat: { foe: { name: 'the hooded poisoner', kind: 'assassin', rel: 0, key: 'cr_well_poisoner' }, context: 'duel', lethal: 0.15, win: { text: 'The jar shattered on the cobbles, harmlessly far from the well. The magistrate found a list in the man’s sleeve: three more towns.', fame: 5, rep: { orthodox: 3 } }, lose: { text: 'He got away, but not with the jar. The well was saved. You were not, quite.', fame: 2 } } })),
    C('Raise the alarm', P('Raise the alarm', 0.6, O('You shouted until the whole street woke. The hooded man vanished, and the jar with him, still sealed.', { fame: 2 }), O('By the time the street woke, the jar was empty and the man was gone. The town drank boiled tea for a month, which saved them.', { fame: 1, sanity: -3 }))),
    C('Walk away', O('You walked away. In the morning you left town without drinking anything.', { sanity: -8, infamy: 1 })),
  ] }),
  E('cr_kidnap', 'crime', { if: { age: [18, 70], locType: 'city', realm: '>=1' }, text: 'A silk merchant’s son has been taken for ransom. The merchant begs any martial artist in the teahouse: "Bring him back. The kidnappers want three hundred taels. I have one hundred."', choices: [
    R('Track the kidnappers', 'insight', 35, O('You followed a trail of sugar-paper wrappers the boy had dropped, clever child, to a mill outside the walls. The kidnappers ran from a fight they could not see coming. The merchant paid you all hundred.', { wealth: 100, fame: 5, rep: { merchants: 5 } }), O('The trail went cold. The merchant paid the ransom with borrowed money, and the boy came home thinner and silent.', { sanity: -3 })),
    C('Deliver the ransom and watch who collects', O('You delivered the ransom, and recognised the collector: the merchant’s own steward. The boy was home by nightfall. The steward was in chains by morning.', { fame: 3, insight: 1, rep: { merchants: 3 } })),
    C('Mind your own business', O('You finished your tea. It had gone cold.', { sanity: -2 })),
  ] }),
  E('cr_tomb_robbers', 'crime', { if: { age: [16, 60], or: [DARK, { stat: { wealth: '<=10' } }], locType: ['wild', 'village', 'frontier'] }, art: 'grave', text: 'Three tomb robbers have found the sealed tomb of a Tang general in the hills. They need a fourth to hold the rope, and they offer an equal share.', choices: [
    P('Hold the rope', 0.6, O('Bronze mirrors, jade cicadas, and a rusted sword. You took your share and did not sleep well for a month.', { wealth: 40, infamy: 2, sanity: -3 }), O('The tomb’s ceiling came down on the second night. You held the rope while two of them climbed out, and one did not.', { sanity: -8, health: -5 })),
    C('Report them to the village', O('The village elders thanked you and resealed the tomb. The robbers left a dead crow on your doorstep.', { fame: 1, sanity: 1 })),
    C('Refuse', O('"More for us," they said. You walked away from a tomb, which you have heard is wise.')),
  ] }),
  E('cr_sect_manual_buyer', 'crime', { if: { faction: ['orthodox', 'families'], rank: [0, 2], age: [14, 40] }, text: 'A pleasant stranger in town buys you dinner and asks, eventually, whether you could copy a few pages of your sect’s heart method. "For a scholar’s collection," he says. "Two hundred taels."', choices: [
    C('Copy the pages', P('Copy the pages', 0.6, O('You copied them by candlelight. The silver was real. Somewhere, a stranger is breathing your sect’s breaths.', { wealth: 200, infamy: 5, sanity: -10, flag: 'cr.sold_manual' }), O('Your senior caught you copying by candlelight. The sect council took less than an hour.', { infamy: 6, expel: true }))),
    C('Report him to the sect', O('Your elders thanked you, and the pleasant stranger was escorted out of the province. He waved as he went.', { merit: 10, rep: { orthodox: 2 } })),
    C('Eat the dinner and say no', O('You ate the dinner and said no. He paid anyway, which was somehow more unsettling.', { health: 1 })),
  ] }),
  E('cr_depot_squeeze', 'crime', { if: { age: [18, 70], sect: 'none', stat: { infamy: '>=10' }, not: 'cr.depot_asked' }, art: 'palace', text: 'An Eastern Depot officer sits down across from you without asking. "We know about you," he says, pleasantly. "We could forget. All you need do is tell us what you hear in the murim."', choices: [
    C('Agree to inform', O('You report once a season to a teahouse with no sign. The Depot pays in silver and in favours. Your old friends would not like it.', { flag: ['cr.depot_asked', 'cr.depot_informer'], wealth: 15, rep: { court: 10, orthodox: -3, unorthodox: -5 }, infamy: -5 })),
    C('Refuse', O('"Everyone refuses once," he said. You are starting to hate that sentence.', { flag: 'cr.depot_asked', rep: { court: -5 } })),
    C('Agree, and feed them lies', R('Agree, and feed them lies', 'insight', 35, O('You fed the Depot carefully useless truths for years. They paid for every one.', { flag: ['cr.depot_asked', 'cr.depot_informer'], wealth: 15, rep: { court: 5 }, insight: 1 }), O('They checked your first report. It did not check out. Your next visit to the teahouse was not pleasant.', { flag: 'cr.depot_asked', health: -15, rep: { court: -10 } }))),
  ] }),
  E('cr_depot_informer_ask', 'crime', { if: { flag: 'cr.depot_informer', age: [18, 80] }, art: 'palace', text: 'The Depot wants more than gossip now: names of Beggars’ Sect members in your city, and where they sleep.', choices: [
    C('Give them names', O('You gave them names. Three beggars disappeared that winter. The Depot paid you double.', { wealth: 30, rep: { court: 10, orthodox: -10 }, sanity: -12, infamy: 4 })),
    C('Warn the Beggars instead', O('You warned the Beggars and gave the Depot names of men already dead. The Depot noticed eventually, but by then you had left town.', { unflag: 'cr.depot_informer', rep: { court: -10, orthodox: 5 }, sanity: 4 })),
    C('Quit, and take your chances', O('You stopped going to the teahouse with no sign. Nothing happened for a long time, which was worse than something happening.', { unflag: 'cr.depot_informer', rep: { court: -8 } })),
  ] }),

  // ── Cult and shadows ────────────────────────────────────────────
  E('cr_cult_smuggle', 'crime', { if: { faction: 'cult', age: [16, 60] }, art: 'desert', text: 'The Shadow Hall needs Cult elixirs carried east to believers in the Central Plains, in tea bricks with false bottoms. The pay is good. The penalty, if the Alliance catches you, is not discussed.', choices: [
    R('Carry the tea', 'charm', 28, O('Three checkpoints, three bored guards, and a merchant’s smile. The believers in Luoyang wept when they saw the red seals.', { merit: 10, wealth: 15, rep: { cult: 5 }, flag: 'cr.smuggler' }), O('A guard at the Jade Gate broke a tea brick open. You ran, and left the Cult’s elixirs and your good name behind.', { infamy: 4, merit: -5, rep: { orthodox: -5 } })),
    C('Decline politely', O('"The Hall will remember your politeness," the courier said. It did not sound like a compliment.', { merit: -2 })),
  ] }),
  E('cr_shadow_hall', 'crime', { if: { faction: 'cult', age: [16, 60], realm: '>=1', alive: 'shadow_master' }, art: 'demonic', text: '{@shadow_master} of the Shadow Hall has not blinked in your presence once. "The Hall needs eyes in the Murim Alliance," he says. "You have unremarkable eyes. It is a compliment."', choices: [
    C('Become a Shadow Hall spy', O('You were given a false name, a false history and a real knife. You leave for Luoyang in the spring.', { meet: '@shadow_master', flag: 'cr.cult_spy', merit: 15, travel: 'luoyang' })),
    C('Ask what happens to spies who are caught', O('He considered the question. "They are not caught," he said, "for long." You declined. He did not seem to mind.', { meet: '@shadow_master', insight: 1 })),
  ] }),
  E('cr_cult_spy_alliance', 'crime', { if: { flag: 'cr.cult_spy', age: [16, 70], loc: 'luoyang' }, danger: true, art: 'city', text: 'Your false name has got you a clerk’s post in the Murim Alliance’s hall in Luoyang. Tonight you could copy the Alliance’s list of informants inside the Cult.', choices: [
    R('Copy it', 'insight', 38, O('You copied it by moonlight and sent it west. Within a season, the Alliance’s eyes in the Cult had closed one by one.', { merit: 30, rep: { cult: 15, orthodox: -10 }, sanity: -12, unflag: 'cr.cult_spy', travel: 'tenthousand' }), O('A Beggar sweeping the hall saw you. You were over the wall by dawn, your false name burned behind you.', { unflag: 'cr.cult_spy', infamy: 5, travel: 'tenthousand' })),
    C('Burn the list instead', O('You burned the list. The Alliance’s informants are safe from the Cult, and from you. You told the Shadow Hall it was too well guarded.', { unflag: 'cr.cult_spy', sanity: 5, merit: -5 })),
    C('Defect to the Alliance', O('You walked into the Alliance Leader’s office and told him everything. He thanked you warmly and had you watched for the rest of your life.', { unflag: 'cr.cult_spy', leave: true, rep: { orthodox: 10, cult: -30 }, infamy: -5 })),
  ] }),

  // ── Gambling ────────────────────────────────────────────────────
  E('cr_gamble_ghost_hand', 'crime', { on: 'gamble', if: { age: [16, 90], wealth: '>=20' }, art: 'inn', text: 'The quiet old man at the end of the table is the Ghost Hand, they whisper, who once won a county magistrate’s seal at dice. He nods at you. "One throw. Your purse against mine."', choices: [
    P('Throw', 0.45, O('You won. The Ghost Hand laughed, emptied his purse into yours, and told you never to play him again. You suspect he let you win.', { wealth: 30, fame: 1 }), O('You lost. He gave you back a single tael "for the road," which was more humiliating than taking it.', { wealth: -20 })),
    R('Watch his hands first', 'insight', 40, O('You saw it: the dice changed in his palm between cup and table. You said nothing, only smiled. He bought you wine and taught you to watch for it.', { insight: 2, codex: { id: 'secret.cr_ghost_hand', cat: 'people', title: 'The Ghost Hand', text: 'The Ghost Hand, an old gambler of the river towns, cheats with a palmed second pair of dice. Smile at him knowingly and he will buy the wine.' } }), O('You watched all night and saw nothing. Either he is honest or he is very good.', { insight: 1 })),
    M('Smile at him knowingly', 'secret.cr_ghost_hand', O('You smiled. He froze, then laughed and pushed his purse across without a throw. "Another life, another table," he said, oddly.', { wealth: 25 })),
    C('Decline', O('"Wise," said the Ghost Hand, and looked a little lonely.')),
  ] }),
  E('cr_gamble_debt', 'crime', { on: 'gamble', if: { age: [16, 90], wealth: '<=5' }, once: false, cd: 4, text: 'You lost again, and the house is happy to extend credit. The house is always happy to extend credit.', choices: [
    C('Take the credit and play on', P('Take the credit and play on', 0.35, O('You won it all back, and a little more, and walked away shaking.', { wealth: 15 }), O('You lost the credit too. Now the house owns a piece of you.', { flag: 'cr.debt', next: { id: 'cr_debt_due', in: 3 } }))),
    C('Get up and leave', O('You got up and left. The dice rattled behind you all the way down the street.', { sanity: 2 })),
  ] }),
];

// ── Template: prisons (reached by `next` from heists, smuggling runs and hunters) ─────────────
// Each prison has its own way out, its own price, and a weakness you learn by serving time there,
// which a later life can use.
const tplPrison = template('cr_prison', [
  { key: 'capital', title: 'The Eastern Depot dungeon', text: 'The Eastern Depot’s dungeon under the capital has no windows and no names, only numbers. Yours is painted on the door in red.',
    esc: 'Wait for the spring floods', stat: 'sanity', dc: 50, out: 'When the spring rains came you were ready, and you went out with the water. The Depot lists you as drowned.', caught: 'The flood came and went and you were still in your cell, wet and older.', nofx: { health: -10, sanity: -5 },
    alt: Q('Name someone the Depot wants more', { stat: { insight: '>=30' } }, O('You traded a name for your freedom. The Depot kept its word. You will not keep the memory easily.', { sanity: -12, rep: { court: 5, orthodox: -5 }, flag: 'cr.jailbird' })),
    serve: 'You served a year in the dark, breathing slowly to stay sane, and they released you without a word of explanation.', serveFx: { sanity: -8, flag: 'cr.jailbird', seclude: 1 },
    mem: { id: 'secret.cr_depot_drain', cat: 'secrets', title: 'The Depot dungeon’s weakness', text: 'The Eastern Depot’s dungeon floods every spring. The drain grate in the third cell from the stairs is rusted through.' },
    memText: 'Go to the third cell’s rusted grate', memOut: 'You remembered the grate from another life. It gave on the first pull.' },
  { key: 'luoyang', title: 'The Alliance cells', text: 'The Murim Alliance keeps its own cells under the Hall of Righteousness in Luoyang. The jailers are Orthodox disciples doing a penance of their own, and they look at you with tired sympathy.',
    esc: 'Talk a jailer into an open door', stat: 'charm', dc: 35, out: 'A young Wudang jailer agreed that you had been wronged, at length, and forgot to lock up. You hope he is not punished.', caught: 'The jailer agreed that you had been wronged, and locked the door anyway.', nofx: { sanity: -3 },
    alt: Q('Pay the Alliance’s fine (50 taels)', { wealth: '>=50' }, O('The Alliance accepted your fine and a written apology, in that order.', { wealth: -50, flag: 'cr.jailbird', rep: { orthodox: 2 } })),
    serve: 'You served your season copying scriptures for the Alliance library. Your handwriting improved. Your opinion of the Alliance did not.', serveFx: { insight: 2, infamy: -2, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_alliance_keys', cat: 'secrets', title: 'The Alliance jailers', text: 'The Alliance jailers under the Hall of Righteousness are penitent disciples. The Wudang ones will open a door for anyone who quotes the Daodejing correctly.' },
    memText: 'Quote the Daodejing to the Wudang jailer', memOut: '"The softest thing in the world overcomes the hardest," you said. He sighed, and opened the door.' },
  { key: 'kaifeng', title: 'The prefecture jail', text: 'Kaifeng’s prefecture jail is run for profit. Everything has a price here: blankets, water, a cell with a window, a trial.',
    esc: 'Slip out with the night-soil cart', stat: 'body', dc: 30, out: 'It was the worst hour of your life and the cart driver never looked back. You were free and very much in need of a bath.', caught: 'The cart driver was paid to look back. You got a beating and a smaller cell.', nofx: { health: -12 },
    alt: Q('Buy a trial (25 taels)', { wealth: '>=25' }, O('Twenty-five taels bought a trial, and the trial found that you had been punished enough.', { wealth: -25, flag: 'cr.jailbird' })),
    serve: 'You served two seasons, and spent them learning which guards sold what to whom. It was an education.', serveFx: { insight: 2, health: -5, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_kaifeng_jailer', cat: 'people', title: 'Jailer Tak of Kaifeng', text: 'Jailer Tak of the Kaifeng prefecture jail owes the Ghost Market forty taels and will open any cell for anyone who promises to pay it.' },
    memText: 'Offer to clear Jailer Tak’s debt', memOut: 'You named the debt and the market. Jailer Tak went pale, then opened the door himself.' },
  { key: 'hangzhou', title: 'The counting-house cellar', text: 'The Golden Abacus Guild does not trouble the magistrate with small thieves. It keeps them in a dry cellar under its counting house, and adds the cost of their keep to their debt.',
    esc: 'Climb the coal chute', stat: 'body', dc: 28, out: 'You came out of the coal chute black from head to foot and walked straight through the market, unrecognised.', caught: 'A clerk caught you halfway up and added the chute’s cleaning to your bill.', nofx: { wealth: -10 },
    alt: R('Offer to keep their books honest', 'insight', 30, O('You found three errors in the Guild ledgers in one night. They released you with a job offer, which you are still considering.', { flag: 'cr.jailbird', rep: { merchants: 6 } }), O('The ledgers were perfect. That was what frightened you.', { sanity: -2 })),
    serve: 'You worked off your keep counting coins for a season. You have never hated arithmetic more.', serveFx: { wealth: -5, insight: 1, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_abacus_ledger', cat: 'secrets', title: 'The Guild’s second ledger', text: 'Under the Golden Abacus counting house in Hangzhou, a second ledger records the bribes Geum Man-bok pays to Hangzhou’s prefect. Mentioning it opens doors.' },
    memText: 'Mention the second ledger', memOut: 'You mentioned the second ledger, softly. You were out within the hour, with a gift of tea.' },
  { key: 'changan', title: 'The Chang’an county jail', text: 'The Chang’an county jail is older than the dynasty. The walls have been written on by a thousand prisoners, and some of the poems are very good.',
    esc: 'Wait for the magistrate’s birthday amnesty', stat: 'sanity', dc: 35, out: 'The magistrate turned sixty and pardoned every second prisoner in honour of the occasion. You were second.', caught: 'You were first. You stayed.', nofx: { sanity: -6 },
    alt: Q('Bribe the clerk (15 taels)', { wealth: '>=15' }, O('The clerk misspelled your name in the register, and the prisoner who did not exist was released at dawn.', { wealth: -15, flag: 'cr.jailbird' })),
    serve: 'You served a season reading the walls. One poem, signed by a man two centuries dead, you will never forget.', serveFx: { insight: 2, sanity: 3, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_wall_poem', cat: 'secrets', title: 'The poem on the wall', text: 'A poem on the wall of the Chang’an county jail, two centuries old, names the magistrate’s ancestor as a thief. Quoting it makes the magistrate very generous.' },
    memText: 'Recite the poem on the wall to the magistrate', memOut: 'You recited it. The magistrate went red, then white, and released you before you could reach the last line.' },
  { key: 'chengdu', title: 'The Chengdu jail', text: 'Chengdu’s jail is hot, crowded and smells of pepper, because the jailers cook their dinner in the corridor.',
    esc: 'Start a brawl and slip out in it', stat: 'power', dc: 30, out: 'Pepper, a cooking pot and twenty prisoners. In the chaos, nobody noticed one fewer.', caught: 'You started the brawl and were the only one caught for it.', nofx: { health: -10, infamy: 1 },
    alt: Q('Pay for a physician’s pass (20 taels)', { wealth: '>=20' }, O('A physician declared you contagious. The jailers could not get you out fast enough.', { wealth: -20, flag: 'cr.jailbird' })),
    serve: 'You served two seasons and learned to cook with a jailer’s pepper. You will never eat bland food again.', serveFx: { health: 3, charm: 1, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_chengdu_cook', cat: 'people', title: 'The Chengdu jail cook', text: 'The chief jailer of Chengdu is homesick for his mother’s mapo tofu. A prisoner who cooks it for him walks out at dawn.' },
    memText: 'Cook mapo tofu for the chief jailer', memOut: 'He ate it in silence, wiped his eyes, and walked you to the gate himself.' },
  { key: 'wuchang', title: 'The prison hulk', text: 'Wuchang keeps its prisoners on an old grain ship moored in the river. It is damp, it rocks, and at night you can hear the Great River laughing at you.',
    esc: 'Swim for it', stat: 'body', dc: 35, out: 'You went over the side in the dark and let the Great River carry you three miles downstream. It is the only thing in Wuchang that ever did you a favour.', caught: 'The current threw you back against the hull. The guards fished you out with a boat hook.', nofx: { health: -15 },
    alt: Q('Bribe the boatman (30 taels)', { wealth: '>=30', noMem: 'secret.cr_hulk_rope' }, O('The supply boatman took you ashore among the rice sacks.', { wealth: -30, flag: 'cr.jailbird' })),
    serve: 'You served a season on the hulk. You learned the tides, and that the night guard sleeps when the river is high.', serveFx: { body: 1, health: -5, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_hulk_rope', cat: 'secrets', title: 'The prison hulk’s tide', text: 'On Wuchang’s prison hulk the night guard sleeps when the river is high, and there is an old mooring rope at the stern that reaches the water.' },
    memText: 'Wait for high water and the stern rope', memOut: 'High water, a sleeping guard, the old rope. You were ashore before the moon set.' },
  { key: 'namgung', title: 'The Hall of Reflection', text: 'The Namgung do not have a prison. They have the Hall of Reflection, a bare room where those who offend the family sit and think about it, sometimes for years.',
    esc: 'Climb out through the roof beams', stat: 'body', dc: 40, out: 'You went up through the beams and over the tiles. A Namgung guard saw you, and decided he had not.', caught: 'The beams held you; the tiles did not. You fell back into the Hall of Reflection and reflected on that.', nofx: { health: -10 },
    alt: R('Ask to speak with the patriarch', 'charm', 40, O('Namgung Hwi heard you out in silence and released you on your word. "Keep it," he said. "The Namgung remember broken words."', { flag: 'cr.jailbird', rep: { families: 3 } }), O('The patriarch did not come. A steward did, and said he would not.', { sanity: -3 })),
    serve: 'You sat in the Hall of Reflection for a year. You came out calmer than you went in, which annoyed the Namgung.', serveFx: { sanity: 6, flag: 'cr.jailbird', seclude: 1 },
    mem: { id: 'secret.cr_namgung_hall', cat: 'secrets', title: 'The Hall of Reflection', text: 'Any prisoner in the Namgung Hall of Reflection may demand the right of the bell: one strike, and the patriarch must hear their case in person.' },
    memText: 'Demand the right of the bell', memOut: 'You struck the bell. The whole estate went silent. The patriarch heard your case, and let you go.' },
  { key: 'tenthousand', title: 'The Cave of Repentance', text: 'The Cult keeps those it is disappointed in at the Cave of Repentance, high on a black peak. Nobody guards it. The cliff does that.',
    esc: 'Climb down the cliff', stat: 'body', dc: 45, out: 'You climbed down for a day and a night with nothing below you but cloud. At the bottom, a shepherd gave you goat’s milk and did not ask.', caught: 'Halfway down, the rock decided otherwise. You climbed back up with a broken arm.', nofx: { injury: { name: 'broken arm', seasons: 4, sev: 15 } },
    alt: R('Petition the Elders for a chance to prove yourself', 'power', 40, O('The Elders sent you to fight a Demon Warrior in the yard. You won, and that was your pardon.', { flag: 'cr.jailbird', rep: { cult: 5 }, merit: 5 }), O('You lost the fight in the yard, and were sent back up the peak.', { health: -10 })),
    serve: 'You repented for a year in the cave, which in practice meant meditating in a wind that never stopped.', serveFx: { flag: 'cr.jailbird', seclude: 1 },
    mem: { id: 'secret.cr_cave_path', cat: 'secrets', title: 'The goat path', text: 'From the Cult’s Cave of Repentance, a goat path runs down the east side of the peak, invisible from the cave mouth.' },
    memText: 'Take the goat path down the east side', memOut: 'You followed the goats. They knew the way. They always did.' },
  { key: 'taihang', title: 'The Green Forest stockade', text: 'The Green Forest keeps its prisoners in a log stockade until someone pays for them. Nobody has come to pay for you. The bandits are starting to find this funny.',
    esc: 'Wait until the feast night', stat: 'insight', dc: 28, out: 'On the feast night the whole stronghold was drunk by moonrise. You walked out past a guard who toasted you.', caught: 'You went too early. The guard was sober and in a bad mood.', nofx: { health: -10 },
    alt: R('Challenge the captain for your freedom', 'power', 30, O('You beat the captain in front of his men. By Green Forest law, that made you free and him embarrassed.', { flag: 'cr.jailbird', fame: 2, rep: { unorthodox: 3 } }), O('The captain beat you in front of his men. They cheered him; at least nobody cheered against you.', { health: -12 })),
    serve: 'You worked a season in the stronghold kitchens until a captain decided you had paid your way.', serveFx: { body: 1, rep: { unorthodox: 2 }, flag: 'cr.jailbird' },
    mem: { id: 'secret.cr_gf_password', cat: 'secrets', title: 'The Green Forest password', text: 'The Green Forest strongholds of the Taihang share one password, changed every new moon but always a line from the Water Margin. This moon: "Brothers within the four seas."' },
    memText: 'Give the stockade guard the password', memOut: '"Brothers within the four seas," you said. The guard stared, then let you out, and asked which stronghold you were from.' },
], (r) => E('cr_prison', 'crime', { on: 'scheduled', art: 'prison', title: r.title, text: r.text, choices: [
  R(r.esc, r.stat, r.dc, O(r.out, { flag: 'cr.jailbird', infamy: 2 }), O(r.caught, r.nofx)),
  r.alt,
  C('Serve your time', O(r.serve, { ...r.serveFx, codex: r.mem })),
  M(r.memText, r.mem.id, O(r.memOut, { flag: 'cr.jailbird', insight: 1 })),
] }));

// ── Template: heists, one per target ────────────────────────────────────────────────────────
const tplHeist = template('cr_heist', [
  { key: 'luoyang', loc: 'luoyang', art: 'city', text: 'The Murim Alliance’s treasurer in Luoyang keeps the dues of nine sects in a strongroom that everyone agrees is impossible to rob. Everyone has been agreeing for a long time.',
    go: 'Rob the impossible strongroom', stat: 'insight', dc: 45, win: 'It was not impossible. It was only badly guarded by people who believed it was. The Alliance has announced nothing, which is how you know it hurt.', loot: { wealth: 150, rep: { orthodox: -5 } }, inf: 6,
    lose: 'The strongroom was impossible after all. So was the stairway out.',
    alt: C('Tip off the Beggars’ Sect instead', O('You told the Beggars the treasurer skims the dues. They already knew; now they knew you knew. Hong Chil sent you a chicken leg, which is high praise.', { rep: { orthodox: 3 }, meet: '@beggar_chief' })) },
  { key: 'hangzhou', loc: 'hangzhou', art: 'lake', text: 'Geum Man-bok of the Golden Abacus Guild is hosting a banquet on a pleasure boat on West Lake, and has left his counting house in the care of two clerks and a cat.',
    go: 'Visit the counting house', stat: 'body', dc: 30, win: 'The clerks were asleep and the cat was bribable. You came away with a purse of gold leaf and the Guild’s best brush.', loot: { wealth: 80, rep: { merchants: -8 } }, inf: 4,
    lose: 'The cat was not bribable. It woke the clerks, the clerks woke the street.',
    alt: Q('Gatecrash the banquet instead', { stat: { charm: '>=30' } }, O('You ate Geum Man-bok’s food, drank his wine and won forty taels from his guests at dice. He toasted you without ever learning your name.', { wealth: 40, charm: 1 })) },
  { key: 'capital', loc: 'capital', art: 'palace', text: 'A eunuch of the Eastern Depot has a mansion in the capital stuffed with confiscated murim treasures. Every one of them belonged to someone who is no longer alive to want it back.',
    go: 'Liberate the treasures', stat: 'insight', dc: 40, win: 'You took a sword, three scrolls and a jade seal, and left the eunuch a note in the original owners’ names. The Depot raged for a month.', loot: { item: { fine_sword: 1 }, wealth: 50, rep: { court: -10 }, fame: 2 }, inf: 5,
    lose: 'The mansion had more guards than treasures, and every guard wore Depot black.',
    alt: R('Steal back one sword for its owner’s widow', 'body', 25, O('You took only the sword. The widow wept over it and could not pay you. You did not want paying.', { fame: 3, sanity: 6 }), O('Even the one sword was too many. You ran with nothing.', { health: -6 })) },
  { key: 'kaifeng', loc: 'kaifeng', art: 'night', text: 'The biggest gambling house in Kaifeng is run by a man who cheats farmers out of their land deeds. His vault is under the dice hall, and tonight is the busiest night of the year.',
    go: 'Go down while the hall is roaring', stat: 'body', dc: 32, win: 'You came up with a box of land deeds and burned the ones that had been won with loaded dice. Twenty families got their fields back.', loot: { wealth: 40, fame: 3, sanity: 4 }, inf: 3,
    lose: 'A bouncer came down for wine and found you instead.',
    alt: R('Beat him at his own game', 'insight', 38, O('You won his deeds back at his own crooked table, with his own crooked dice. He could not complain without confessing.', { wealth: 30, fame: 2 }), O('His dice were more crooked than your eye was sharp.', { wealth: -15 })) },
  { key: 'changan', loc: 'changan', art: 'city', text: 'An antique dealer in Chang’an is selling a jade horse from a Tang emperor’s tomb. He bought it from tomb robbers, and he is asking a fortune.',
    go: 'Take the jade horse', stat: 'body', dc: 28, win: 'You took it and sold it to a collector in a different city, who asked no questions and paid in gold.', loot: { wealth: 90 }, inf: 3,
    lose: 'The dealer’s shop was guarded by his sons, all five of them, all large.',
    alt: C('Return it to the tomb', O('You carried the jade horse into the hills and put it back where it belonged. Nobody will ever know. You will.', { sanity: 8, fame: 1 })) },
  { key: 'chengdu', loc: 'chengdu', art: 'market', text: 'Chengdu’s brocade warehouses hold a year of the city’s silk. One warehouse belongs to a merchant who pays his weavers in promises.',
    go: 'Empty his warehouse', stat: 'power', dc: 30, win: 'Twenty bolts of brocade, and a weaver who helped you load the cart. You split it with her, and she split hers with forty others.', loot: { wealth: 60, fame: 1 }, inf: 3,
    lose: 'The night watch was larger than the merchant’s pay rolls suggested.',
    alt: R('Organise the weavers instead', 'charm', 35, O('You talked forty weavers into putting down their shuttles. The merchant paid them in silver within a week.', { fame: 3, rep: { merchants: -3 } }), O('The weavers were too afraid. You were not afraid enough.', { sanity: -3 })) },
  { key: 'wuchang', loc: 'wuchang', art: 'river', text: 'The salt commissioner’s barge is moored at Wuchang overnight. Salt is the emperor’s monopoly, and the commissioner’s private fortune.',
    go: 'Board the barge', stat: 'body', dc: 30, win: 'You took the commissioner’s strongbox and dropped his salt ledger in the river. Downstream, nobody wept.', loot: { wealth: 70, rep: { court: -5 } }, inf: 4,
    lose: 'The barge was full of marines who had been told to expect someone.',
    alt: C('Tell the Water Fortress where it is', O('You sold the barge’s location to a Water Fortress scout for a fair price. By morning the barge was in the reeds.', { wealth: 25, rep: { unorthodox: 4 }, flag: 'cr.smuggler' })) },
  { key: 'namgung', loc: 'namgung', art: 'estate', if: { not: 'cr.namgung_armory' }, text: 'The Namgung armory holds swords older than most dynasties. The estate is full of guests for the patriarch’s birthday, and the guards are watching the guests.',
    go: 'Slip into the armory', stat: 'insight', dc: 42, win: 'You took one blade, from the back, that nobody had drawn in a century. It is beautiful, and it will be missed.', loot: { item: { fine_sword: 1 }, rep: { families: -10 }, flag: 'cr.namgung_armory' }, inf: 5,
    lose: 'The Namgung armory was the one place the guards were watching.',
    alt: C('Steal a cake from the birthday banquet', O('You stole a peach-shaped birthday bun from the patriarch’s own table. It was delicious, and the only crime of your life you are entirely proud of.', { sanity: 3, charm: 1 })) },
  { key: 'tenthousand', loc: 'tenthousand', art: 'demonic', if: { faction: 'cult' }, text: 'The Cult’s elixir store sits behind the Hall of Ten Thousand Demons, guarded by believers who have never been tempted, because they have never been hungry.',
    go: 'Raid the elixir store', stat: 'power', dc: 40, win: 'You came away with a Foundation-Settling Pill and the giddy terror of a believer who has robbed his own god.', loot: { item: { foundation_pill: 1 }, merit: -10, rep: { cult: -5 } }, inf: 3,
    lose: 'A believer caught you with your hand in the jar. The Elders were very disappointed.',
    alt: C('Tell the Elders the store is unguarded on feast days', O('You reported the weakness. The Elders rewarded your vigilance with the pill you had been planning to steal.', { item: { qi_pill: 2 }, merit: 8 })) },
  { key: 'taihang', loc: 'taihang', art: 'mountain', if: { notSect: 'greenforest' }, text: 'A Green Forest stronghold keeps a year of stolen silver in a cave under its hall. Robbing bandits is either the bravest or the stupidest thing a person can do in Hebei.',
    go: 'Rob the robbers', stat: 'body', dc: 35, win: 'You walked out with a sack of silver and walked into a legend. Teahouses all over Hebei tell it wrong.', loot: { wealth: 100, fame: 4, rep: { unorthodox: -10 } }, inf: 2,
    lose: 'The bandits had been robbed before, and had learned.',
    alt: R('Return the silver to the villages it came from', 'body', 35, O('You carried what you could down the mountain and left it on doorsteps. The bandits blamed each other for a year.', { fame: 5, sanity: 5, rep: { unorthodox: -5 } }), O('You got as far as the cave mouth.', { next: 'cr_prison.taihang' })) },
], (r) => E('cr_heist', 'crime', { if: { ...DARK, loc: r.loc, age: [15, 65], ...(r.if || {}) }, once: false, cd: 6, art: r.art, text: r.text, choices: [
  R(r.go, r.stat, r.dc, O(r.win, { ...r.loot, infamy: r.inf, flag: 'cr.burglar' }), O(r.lose, { infamy: Math.ceil(r.inf / 2), next: `cr_prison.${r.key}` })),
  r.alt,
  C('Walk away', O('You walked away. The target will be there next year, and so, probably, will you.')),
] }));

// ── Template: smuggling, one per route ─────────────────────────────────────────────────────
const tplSmuggle = template('cr_smuggle', [
  { key: 'salt', region: 'jingchu', jail: 'wuchang', text: 'Untaxed salt from the marshes, upriver to Luoyang. Salt is the emperor’s monopoly; the emperor’s inspectors are Wuchang’s most expensive habit.',
    go: 'Run the salt upriver', stat: 'charm', dc: 25, win: 'You talked your way past four inspection posts with a barge full of "pickled radishes." The radishes were very salty.', pay: { wealth: 40 }, alt: Q('Pay the inspectors in advance (15 taels)', { wealth: '>=15' }, O('You paid ahead. The inspectors were punctual, polite and blind.', { wealth: 25 })) },
  { key: 'teahorse', region: 'shu', jail: 'chengdu', text: 'The tea-horse road climbs out of Shu into the mountains. Tibetan traders pay in horses for tea that never saw a tax stamp.',
    go: 'Walk the tea-horse road', stat: 'body', dc: 30, win: 'Six weeks of mountain paths with a tea brick on your back, and a horse to ride home. Your legs will never be the same.', pay: { wealth: 30, body: 2 }, alt: C('Hire on as a porter only', O('You carried tea and asked no questions, and were paid like it.', { wealth: 10, body: 1 })) },
  { key: 'silk', region: 'jiangnan', jail: 'hangzhou', text: 'Hangzhou silk, without the Guild’s seal, bound for a caravan that leaves the Jade Gate next month. The Golden Abacus Guild considers this a sin worse than murder.',
    go: 'Take the silk west', stat: 'insight', dc: 30, win: 'Forged Guild seals, a forged caravan pass, and a very real profit at the Jade Gate.', pay: { wealth: 60, rep: { merchants: -6 } }, alt: R('Sell the Guild the smuggler’s name', 'charm', 25, O('The Guild paid handsomely for the name and asked no questions about yours.', { wealth: 20, rep: { merchants: 5 }, sanity: -3 }), O('The Guild paid for the name, and then asked about yours.', { rep: { merchants: -3 } })) },
  { key: 'cultpills', region: 'west', jail: 'tenthousand', if: { faction: ['cult', 'unorthodox'] }, text: 'Cult elixirs fetch ten times their weight in silver in the Central Plains, where they are banned. The Shadow Hall turns a blind eye, for a cut.',
    go: 'Carry Cult elixirs east', stat: 'charm', dc: 32, win: 'Believers in the east bought every pill. The Shadow Hall took its cut and left you more than you expected.', pay: { wealth: 50, rep: { cult: 4, orthodox: -4 } }, alt: C('Keep a pill for yourself', O('You kept one back. It burned like a coal in your dantian.', { item: { qi_pill: 1 }, qi: 10 })) },
  { key: 'iron', region: 'hebei', jail: 'taihang', text: 'Iron is forbidden to the Green Forest by imperial decree, which is why the Green Forest pays so well for it.',
    go: 'Haul iron into the Taihang', stat: 'body', dc: 28, win: 'Three mule-loads of iron up the bandit roads. Ma Hu’s quartermaster paid in silver and in an invitation you did not accept.', pay: { wealth: 35, rep: { unorthodox: 6, court: -4 } }, alt: C('Sell the iron to the village smiths instead', O('Ploughs, not sabers. The pay was half, and you slept twice as well.', { wealth: 15, sanity: 3 })) },
  { key: 'ginseng', region: ['liaodong', 'hebei'], jail: 'capital', text: 'Wild mountain ginseng from Liaodong, dug without a permit and worth a fortune in the capital’s pharmacies.',
    go: 'Carry the ginseng south', stat: 'insight', dc: 30, win: 'You hid the roots in a cartload of turnips and sold them to an imperial pharmacist who knew exactly what they were.', pay: { wealth: 55 }, alt: QP('Look for a truly old root among them', { stat: { insight: '>=30' } }, 0.15, O('Among the roots was one older than the dynasty. You kept it.', { item: { spirit_ginseng: 1 } }), O('They were all young roots. You sold them anyway.', { wealth: 30 })) },
  { key: 'weapons', region: 'jingchu', jail: 'wuchang', if: { or: [{ faction: 'unorthodox' }, { stat: { infamy: '>=10' } }] }, text: 'A crate of crossbows from an imperial arsenal, "misplaced" by a quartermaster, bound for the Water Fortress.',
    go: 'Deliver the crossbows', stat: 'power', dc: 32, win: 'You delivered them under the noses of two patrols. Gyeong Pa’s quartermaster paid, and remembered your face.', pay: { wealth: 45, rep: { unorthodox: 8, court: -8 } }, alt: C('Dump the crate in the river', O('You dropped the crossbows in the deepest part of the river and told everyone the crate was stolen. Nobody believed you, and nobody could prove anything.', { sanity: 4, rep: { unorthodox: -4 } })) },
  { key: 'manuals', region: 'hebei', jail: 'capital', text: 'The Eastern Depot has been confiscating murim manuals. A Depot clerk will sell copies out the back door, if someone will carry them out of the capital.',
    go: 'Smuggle the manuals out', stat: 'insight', dc: 35, win: 'You walked out of the capital with a box of manuals under a load of laundry. The sects you returned them to paid in gratitude, and occasionally in silver.', pay: { wealth: 30, rep: { orthodox: 5, court: -6 }, fame: 2 }, alt: C('Read them first', O('You read a little of everything before you delivered it. It is surprising how much the sects disagree about breathing.', { insight: 3 })) },
  { key: 'refugees', region: 'shu', jail: 'chengdu', if: { flag: 'w.plague' }, text: 'The plague gates of Chengdu are shut, and the healthy are trapped with the sick. A boatman will take families out by the river, at night, if someone will row the second boat.',
    go: 'Row the second boat', stat: 'body', dc: 30, win: 'You rowed out three families before dawn. A child slept on your feet the whole way.', pay: { fame: 5, sanity: 8 }, alt: Q('Pay the guards to look away (40 taels)', { wealth: '>=40' }, O('The guards looked away for an hour. In that hour, forty people walked out.', { wealth: -40, fame: 4, sanity: 6 })) },
  { key: 'jadegate', region: 'west', jail: 'tenthousand', text: 'Caravans out past the Jade Gate carry tea and porcelain one way and western horses the other. The customs post takes a tenth. Smugglers take the old road through the dunes.',
    go: 'Take the old dune road', stat: 'body', dc: 34, win: 'Nine days of sand, two of them without water. At the far oasis you sold your porcelain for gold.', pay: { wealth: 50, health: -5 }, alt: R('Charm the customs officer', 'charm', 30, O('He waved your caravan through and asked you to dinner.', { wealth: 30, charm: 1 }), O('He took a tenth, and then a tenth of what was left, for the insult.', { wealth: 5 })) },
], (r) => E('cr_smuggle', 'crime', { if: { region: r.region, age: [16, 65], or: [{ flag: 'cr.smuggler' }, { career: ['merchant', 'escort', 'bandit'] }, { faction: 'unorthodox' }], ...(r.if || {}) }, once: false, cd: 4, art: 'road', text: r.text, choices: [
  R(r.go, r.stat, r.dc, O(r.win, { ...r.pay, flag: 'cr.smuggler', infamy: 1 }), O('The inspectors had been tipped off. Somebody always tips them off.', { infamy: 2, next: `cr_prison.${r.jail}` })),
  r.alt,
  C('Pass on this one', O('You passed. Smugglers live long by passing on most runs.')),
] }));

// ── Template: bounty hunters who come for you ──────────────────────────────────────────────
const tplHunter = template('cr_hunter', [
  { key: 'paeng_exile', if: { stat: { infamy: '>=20' }, region: ['hebei', 'central'] }, text: 'A one-eyed man with a heavy saber is waiting at the crossroads. He was a Paeng once, until the Paeng threw him out. Now he hunts people like you for silver.',
    foe: { name: 'the one-eyed Paeng exile', kind: 'bandit', rel: 0.3, key: 'cr_paeng_exile' }, ctx: 'duel', lethal: 0.15, win: 'He went down laughing. "Paeng blood," he said. "Never could pick a winning side."', lose: { text: 'He took your purse instead of your head. "Your bounty is low," he said. "Grow."', wealth: -25 },
    talk: R('Offer him a drink and a better job', 'charm', 35, O('You got him drunk and talking about his family. By dawn he had decided the bounty was not worth it.', { charm: 1 }), O('He drank your wine and drew his saber anyway.', { health: -15 })),
    memo: 'Strike at his blind side', memOut: 'You remembered his blind eye from another life. One step to the left, and the fight was over before it began.' },
  { key: 'beggar_tracker', if: { stat: { infamy: '>=25' }, region: 'central' }, text: 'A Six-Pouch elder of the Beggars’ Sect has followed you for three towns. Beggars do not take bounties, he says. They take justice. The difference is mostly paperwork.',
    foe: { name: 'a Six-Pouch Beggar elder', kind: 'brawler', rel: 0.5, key: 'cr_beggar_elder' }, ctx: 'duel', lethal: 0.05, win: 'He sat down in the road, wheezing, and laughed. "Justice will try again tomorrow."', lose: { text: 'He beat you with a dog-beating staff until you promised to make amends, and then made you buy him dinner.', infamy: -3, wealth: -5 },
    talk: Q('Make amends on the spot (30 taels)', { wealth: '>=30' }, O('You gave him thirty taels for the people you had wronged. He counted it, nodded, and went away.', { wealth: -30, infamy: -5, rep: { orthodox: 3 } })),
    memo: 'Ask after Hong Chil’s chicken', memOut: 'You asked after the Clan Chief’s favourite roast chicken stall, from another life. The elder laughed so hard he forgot to arrest you.' },
  { key: 'depot_constable', if: { stat: { infamy: '>=30' }, region: ['hebei', 'central', 'guanzhong'] }, text: 'An Eastern Depot constable in black and silver blocks the road with four men. "By order of the Director," he says, "you are coming with us."',
    foe: { name: 'an Eastern Depot constable', kind: 'soldier', rel: 0.5, key: 'cr_depot_constable' }, ctx: 'ambush', lethal: 0.2, win: 'You scattered them. The Depot will remember that, in triplicate.', lose: { text: 'They took you north in chains.', rep: { court: -5 }, travel: 'capital', next: 'cr_prison.capital' },
    talk: R('Show papers you do not have', 'insight', 40, O('You showed a letter of passage from a prefect who owed you a favour. The constable read it twice and stepped aside.', { insight: 1 }), O('The constable read your papers and laughed. You ran.', { health: -10, infamy: 2 })),
    memo: 'Remind him of his gambling debts', memOut: 'You named the gambling house and the amount, from another life. The constable went pale and found that you did not match the description.' },
  { key: 'emei_nun', if: { stat: { infamy: '>=35' }, region: ['shu', 'jingchu'] }, text: 'An Emei nun has walked a thousand li to find you. She has sworn before the Buddha to bring you to justice, and she does not look like she has ever broken a vow.',
    foe: { name: 'a vow-bound Emei nun', kind: 'disciple', rel: 0.5, key: 'cr_emei_nun' }, ctx: 'duel', lethal: 0.1, win: 'She lowered her sword. "Then the vow is my failure," she said, "not yours." She walked away. You felt worse than if you had lost.', lose: { text: 'She disarmed you and made you kneel in a temple for a season, chanting for the people you had hurt.', infamy: -6, sanity: 4 },
    talk: C('Confess everything to her', O('You told her all of it. She listened to the end. "The Buddha forgives," she said. "I am still deciding." She let you go.', { infamy: -4, sanity: 6 })),
    memo: 'Tell her where the villain she truly seeks is hiding', memOut: 'You remembered who she would hunt next, in another life. You told her now. She left at once, and her vow went with her.' },
  { key: 'twins', if: { stat: { infamy: '>=25' }, locType: ['city', 'village'] }, text: 'Twin brothers in matching blue have been asking about you at every inn in town. They finish each other’s sentences, and probably each other’s fights.',
    foe: { name: 'the Blue Twins', kind: 'brawler', rel: 0.3, key: 'cr_blue_twins' }, ctx: 'duel', lethal: 0.1, win: 'You beat them both, one at a time, and they blamed each other all the way out of town.', lose: { text: 'They beat you, argued about who had done more of it, and forgot to collect the bounty.', health: -5 },
    talk: R('Set them against each other', 'insight', 30, O('You told each, privately, that the other planned to keep the whole bounty. By noon they were brawling in the market.', { insight: 1 }), O('They saw through it together. They do most things together.', { health: -10 })),
    memo: 'Ask which of them is the elder', memOut: 'You remembered that this question had once started a three-day fight between them. It did again.' },
  { key: 'old_escort', if: { stat: { infamy: '>=20' }, age: [20, 90] }, text: 'A grey-haired escort guard with a bad knee stops you on the road. "Sorry about this," he says. "My daughter is getting married. Your bounty is her dowry."',
    foe: { name: 'an old escort guard', kind: 'soldier', rel: 0, key: 'cr_old_escort' }, ctx: 'duel', lethal: 0.05, win: 'You disarmed him gently. He sat down on a stone and looked at his hands for a long time.', lose: { text: 'He won. He looked almost apologetic, and let you go anyway. "She would not want it this way," he said.', health: -5 },
    talk: Q('Give him the dowry (40 taels)', { wealth: '>=40' }, O('You gave him forty taels. He wept, and invited you to the wedding. You went, under a false name, and danced.', { wealth: -40, sanity: 8, fame: 1 })),
    memo: 'Ask after his daughter by name', memOut: 'You knew her name from another life. The old man stared at you, then put his sword away. "Tell me how she is," he said. You did.' },
  { key: 'pavilion_rogue', if: { stat: { infamy: '>=40' }, notSect: 'bloodshadow' }, text: 'An assassin who left the Blood Shadow Pavilion now works alone, and a name on a bounty board is easier than a contract. Yours is on a bounty board.',
    foe: { name: 'a rogue Blood Shadow', kind: 'assassin', rel: 0.5, key: 'cr_rogue_shadow' }, ctx: 'ambush', lethal: 0.3, win: 'The rogue Shadow fell back into the dark. The Pavilion sent you a black thread, which you suspect was thanks.', lose: { text: 'You lived because the rogue was after silver, not your life. Your purse did not live.', wealth: -40 },
    talk: R('Tell the rogue the Pavilion is close behind', 'insight', 40, O('You described a Silent Shadow you had seen in town. The rogue went white and left before supper.', { insight: 1 }), O('The rogue did not believe you, and showed you why.', { health: -15 })),
    memo: 'Wait at the spot the rogue always strikes from', memOut: 'You remembered the rooftop from another life, and were sitting on it first. The rogue reconsidered the bounty.' },
  { key: 'namgung_glory', if: { stat: { infamy: '>=45' }, region: ['jiangnan', 'central'] }, text: 'A young Namgung swordsman in white has come to make his name by taking yours. He announces this loudly, in front of a crowd, before he draws.',
    foe: { name: 'a glory-hungry Namgung swordsman', kind: 'disciple', rel: 0.2, key: 'cr_namgung_youth' }, ctx: 'duel', lethal: 0.1, win: 'You beat him in front of the crowd he had gathered. He will never forgive you, and his family will never mention it.', lose: { text: 'He beat you in front of the crowd and became famous overnight. You became a story he tells.', fame: -2, rep: { families: 2 } },
    talk: R('Mock him until he loses his temper', 'charm', 35, O('He lost his temper, then his footing, then the crowd. He went home without drawing.', { fame: 1 }), O('He kept his temper. That was worse.', { health: -10 })),
    memo: 'Mention his elder brother’s duel record', memOut: 'You remembered his brother’s losses from another life, and listed them. The young man went red and walked away to think about his life.' },
  { key: 'dog_handler', if: { stat: { infamy: '>=30' }, region: ['liaodong', 'hebei'] }, text: 'You hear the dogs before you see the hunter. A Liaodong tracker with three hounds has followed your scent through two provinces.',
    foe: { name: 'the Liaodong tracker', kind: 'beast', rel: 0, key: 'cr_dog_handler' }, ctx: 'beast', lethal: 0.15, win: 'The hounds broke and ran, and their master after them. He shouted that he would be back. The dogs did not look as if they agreed.', lose: { text: 'The hounds pinned you until their master arrived to empty your purse.', wealth: -25 },
    talk: R('Make friends with the dogs', 'charm', 40, O('You sat down in the road and held out dried meat. The hounds licked your face. Their master threw up his hands.', { charm: 1, sanity: 3 }), O('The dogs took the meat and then your sleeve.', { health: -10 })),
    memo: 'Cross the river where the scent breaks', memOut: 'You remembered the ford from another life. The hounds lost you at the water, and their master lost his temper.' },
  { key: 'han_gyeong', if: { stat: { infamy: '>=60' }, region: 'hebei', alive: 'guard_commander' }, text: '{@guard_commander} of the Imperial Guard rides alone, which tells you everything about how good he is. "I would rather not do this," he says. "But you have made it hard to look away."',
    foe: '@guard_commander', ctx: 'duel', lethal: 0.1, win: 'He yielded with real grace. "I will tell the court I could not find you," he said. "It will be the first lie of my career."', lose: { text: 'He beat you and did not take you in. "Leave Hebei," he said. "Live better somewhere else." It was not a request.', infamy: -5, travel: 'luoyang' },
    talk: R('Tell him what the Depot Director is planning', 'insight', 45, O('He listened to every word. "If you are right," he said, "I have been hunting the wrong man." He rode back to the capital at a gallop.', { meet: '@guard_commander', rel: { '@guard_commander': { res: 15 } } }), O('He listened, and did not believe you. But he let you go, which from him is a kind of belief.', { meet: '@guard_commander' })),
    memo: 'Tell him he will one day cut down the Director', memOut: 'You told him what you had seen in another life. He was silent for a long while. "Then I had better live," he said, and let you go.' },
], (r) => E('cr_hunter', 'crime', { if: { age: [16, 100], ...r.if }, once: false, cd: 6, danger: true, art: 'road', title: 'A bounty hunter', text: r.text, choices: [
  C('Fight', O('So be it.', { combat: { foe: r.foe, context: r.ctx, lethal: r.lethal, win: { text: r.win, fame: 2, infamy: 1 }, lose: r.lose } })),
  r.talk,
  R('Run', 'body', 30 + Math.round(r.lethal * 40), O('You ran, and did not stop until the next province.', { body: 1 }), O('You did not get far.', { health: -8, wealth: -10 })),
  M(r.memo, `foe.${typeof r.foe === 'string' ? r.foe.slice(1) : r.foe.key}`, O(r.memOut, { insight: 1 })),
] }));

// ── Template: gambling dens, one per city (Gamble or Tavern) ───────────────────────────────
const tplDen = template('cr_den', [
  { key: 'kaifeng', loc: 'kaifeng', text: 'The Golden Toad in Kaifeng is the biggest dice hall in the empire. Three floors of noise, and on the top floor, tables where people bet houses.',
    play: 'Bet on big or small', p: 0.45, win: { wealth: 25 }, lose: { wealth: -20 }, winText: 'Big, three times running. The house sent a girl with free wine, which is how they tell you to leave.', loseText: 'Small, three times running. The house sent a girl with free wine, which is how they tell you to stay.',
    spot: 30, alt: QP('Go up to the top floor (100 taels)', { wealth: '>=100' }, 0.4, O('You won a canal house from a salt merchant who did not seem to mind. You sold it the next day.', { wealth: 150 }), O('You lost a hundred taels in a single throw, very elegantly.', { wealth: -100 })) },
  { key: 'luoyang', loc: 'luoyang', text: 'Under a bridge in Luoyang, the Beggars’ Sect runs a cricket-fighting ring. The crickets have names, records and, in one case, a fan club.',
    play: 'Bet on Iron General', p: 0.55, win: { wealth: 8 }, lose: { wealth: -6 }, winText: 'Iron General won in a flurry of legs. The beggars cheered as if it were the Dragon-Phoenix Assembly.', loseText: 'Iron General lost his nerve and climbed out of the bowl. The fan club wept.',
    spot: 25, alt: C('Buy a fighting cricket of your own', O('You bought a cricket called Little Thunder for two taels. He lost every fight and lived in a gourd on your windowsill for three years.', { wealth: -2, sanity: 3 })) },
  { key: 'hangzhou', loc: 'hangzhou', text: 'On a painted boat on West Lake, merchants play a card game whose rules change every time someone wins.',
    play: 'Play a hand', p: 0.4, win: { wealth: 30, rep: { merchants: 2 } }, lose: { wealth: -25 }, winText: 'You won, and the merchants immediately changed the rules. You left while the rules were still in your favour.', loseText: 'You lost, and the merchants explained a rule nobody had mentioned.',
    spot: 35, alt: R('Learn the rules properly first', 'insight', 30, O('You watched until you understood the real rule: the host always wins. You bet on the host.', { wealth: 15, insight: 1 }), O('There were no rules. That was the rule.', { wealth: -5 })) },
  { key: 'changan', loc: 'changan', text: 'In Chang’an the old money gambles on horse races outside the west gate, and the new money gambles on which old money will go broke first.',
    play: 'Bet on the grey mare', p: 0.35, win: { wealth: 35 }, lose: { wealth: -15 }, winText: 'The grey mare came from behind like a ghost. The bookmaker paid in a very small voice.', loseText: 'The grey mare stopped to eat a flower.',
    spot: 30, alt: R('Ride in the race yourself', 'body', 35, O('You won the race on a borrowed horse and the purse with it, and three noble daughters sent you poems.', { wealth: 30, fame: 2 }), O('You fell off in front of the whole city.', { health: -8, fame: -1 })) },
  { key: 'capital', loc: 'capital', text: 'In the capital, eunuchs of the inner palace bet on quail fights in a teahouse that does not officially exist.',
    play: 'Bet on the emperor’s favourite quail', p: 0.5, win: { wealth: 20, rep: { court: 2 } }, lose: { wealth: -20 }, winText: 'The emperor’s quail won, as it always does, because nobody dares let it lose.', loseText: 'For the first time in living memory, the emperor’s quail lost. Nobody will speak of it. You lost twenty taels and gained a secret.',
    spot: 40, alt: C('Listen to the eunuchs gossip', O('You lost a little and listened a lot. The Director of the Eastern Depot, they said, is planning something for when the boy Emperor comes of age.', { wealth: -3, insight: 1, flag: 'cr.depot_gossip' })) },
  { key: 'wuchang', loc: 'wuchang', text: 'On the Wuchang docks, porters play dice for a day’s wages on an upturned crate, and anyone with silver can sit in.',
    play: 'Sit in', p: 0.5, win: { wealth: 6 }, lose: { wealth: -6 }, winText: 'You won a day’s wages and gave half back for the next round of wine. The porters decided you were all right.', loseText: 'You lost a day’s wages and the porters bought you wine out of pity.',
    spot: 20, alt: C('Play for their wages, and lose on purpose', O('You lost steadily all evening to the most tired-looking porters. They knew. They took it anyway, with dignity.', { wealth: -8, sanity: 4, charm: 1 })) },
  { key: 'chengdu', loc: 'chengdu', text: 'Chengdu’s teahouses run mahjong games that last for days. Players eat, sleep and occasionally die at the table.',
    play: 'Take an empty seat', p: 0.45, win: { wealth: 18 }, lose: { wealth: -12, health: -3 }, winText: 'Two days later you stood up eighteen taels richer and could not feel your legs.', loseText: 'Two days later you stood up twelve taels poorer and could not feel your legs.',
    spot: 30, alt: R('Out-sit the old grandmother at table four', 'sanity', 55, O('You played her for three days. On the fourth she bowed, gave you her winnings and went home to sleep. The teahouse applauded.', { wealth: 25, fame: 1 }), O('She out-sat you. You fell asleep on the tiles and woke up poorer.', { wealth: -10 })) },
  { key: 'dongting', loc: 'dongting', text: 'The Water Fortress runs a floating casino on Lake Dongting. If you lose more than you can pay, they offer you a swimming lesson.',
    play: 'Play fan-tan', p: 0.45, win: { wealth: 20, rep: { unorthodox: 1 } }, lose: { wealth: -15 }, winText: 'You won, and the pirates applauded with genuine sportsmanship, and watched you all the way to the shore.', loseText: 'You lost, but could pay. The pirates were almost disappointed.',
    spot: 35, alt: C('Ask about the swimming lesson', O('They took you to the rail and pointed at the far shore. "Like that," they said. You declined the lesson and bought a round.', { wealth: -4, rep: { unorthodox: 2 } })) },
  { key: 'jadegate', loc: 'jadegate', text: 'At the Jade Gate caravanserai, traders from twenty kingdoms gamble with knucklebones and argue in six languages.',
    play: 'Throw the knucklebones', p: 0.5, win: { wealth: 15 }, lose: { wealth: -10 }, winText: 'You won a pouch of western coins with a stranger’s face on them. They are worth something, somewhere.', loseText: 'A Sogdian trader beat you three times and taught you a curse in his language. You will use it often.',
    spot: 25, alt: C('Trade stories instead of coins', O('You traded a story about Mount Hua for a story about a city with blue domes. You both thought you got the better deal.', { insight: 2, sanity: 2 })) },
  { key: 'taihang', loc: 'taihang', if: { or: [{ sect: 'greenforest' }, { faction: 'unorthodox' }] }, text: 'Round the fire in a Green Forest stronghold, bandits bet their shares of the last raid on a game of who can hold a hot stone longest.',
    play: 'Hold the stone', p: 0.4, win: { wealth: 20, rep: { unorthodox: 3 } }, lose: { health: -6 }, winText: 'You held it longest, and the bandits cheered you hoarse. Your palm will heal. Probably.', loseText: 'You dropped it first. The bandits cheered anyway; it was that kind of night.',
    spot: 30, alt: C('Refuse, and pour the wine instead', O('You poured wine all night and heard every secret in the stronghold.', { insight: 1, rep: { unorthodox: 1 } })) },
], (r) => E('cr_den', 'crime', { on: ['gamble', 'tavern'], if: { loc: r.loc, age: [14, 100], ...(r.if || {}) }, once: false, cd: 3, art: 'inn', text: r.text, choices: [
  P(r.play, r.p, O(r.winText, r.win), O(r.loseText, r.lose)),
  R('Watch for the cheat first', 'insight', r.spot, O('You spotted how the house cheats, bet against it, and walked away ahead.', { wealth: Math.round(r.spot / 3), insight: 1 }), O('You watched and saw nothing. Either it is honest, or you are not as sharp as you think.', { insight: 0.5 })),
  r.alt,
] }));

// ── Template: assassination / sabotage contracts, one per mark ─────────────────────────────
// For the Blood Shadow Pavilion or a working assassin. Every mark has a reason, a price and a way
// to walk it back; the dishonourable path costs infamy and sanity, and there is always a mercy.
const tplContract = template('cr_contract', [
  { key: 'grain_official', if: { region: ['central', 'hebei'] }, text: 'The contract is a granary official who let flood relief rot while a county starved. The client is a village headman who sold his ox to pay the fee.',
    go: 'Carry out the contract', stat: 'body', dc: 25, win: 'The official died of what the coroner called an unlucky fall. The granary doors were found open the next morning.', pay: { wealth: 25, merit: 10 }, inf: 4, san: -6,
    alt: C('Expose him instead', O('You left the rot-ledgers nailed to the prefecture door. He was dismissed, the grain was shared out, and the headman got his ox back.', { fame: 3, merit: 4, rep: { court: -2 } })) },
  { key: 'rival_merchant', if: { region: ['jiangnan', 'central'] }, text: 'A silk merchant wants a rival "removed from competition." The rival is honest, which is apparently the problem.',
    go: 'Take the contract as written', stat: 'insight', dc: 30, win: 'The honest merchant met with an accident. You took the silver and have not spent it, which bothers you.', pay: { wealth: 40 }, inf: 5, san: -10,
    alt: C('Warn the honest merchant and keep the fee', O('You warned the honest merchant, kept the client’s fee, and told the client the job was done. The honest man quietly left town, richer for the warning.', { wealth: 40, infamy: 1, flag: 'cr.double_cross' })) },
  { key: 'corrupt_judge', if: { region: ['guanzhong', 'central'] }, text: 'A magistrate who sells verdicts is the mark. The client is a widow whose husband hanged for a crime the magistrate’s patron committed.',
    go: 'Fulfil the contract', stat: 'body', dc: 28, win: 'The magistrate’s ledger of sold verdicts was found on his body, which the client had not paid for but appreciated.', pay: { wealth: 20, merit: 8, fame: 2 }, inf: 3, san: -5,
    alt: R('Steal the ledger and let the law do it', 'insight', 32, O('You took the ledger of sold verdicts to the circuit censor. The magistrate was executed by the state, which cost the client nothing.', { fame: 4, rep: { court: -3 } }), O('The ledger was better guarded than the man. You came away with neither.', { health: -5 })) },
  { key: 'cult_defector', if: { faction: 'cult' }, text: 'The Shadow Hall wants a defector silenced before he reaches the Alliance with what he knows. He was your year-mate once.',
    go: 'Silence him', stat: 'body', dc: 32, win: 'You caught him at the border. He did not run. "I knew it would be you," he said. The Hall was pleased. You were not.', pay: { merit: 20, wealth: 15 }, inf: 3, san: -12,
    alt: C('Let him go and report him dead', O('You let him cross the border and told the Hall the job was done. If the Alliance ever parades him, you are a dead man.', { flag: 'cr.double_cross', merit: 10, sanity: 4 })) },
  { key: 'sect_elder', if: { region: ['central', 'guanzhong', 'shu'] }, text: 'An Orthodox sect elder is the mark. The client will not say why, only that it is just. The elder spends his evenings teaching orphans to read.',
    go: 'Complete the contract', stat: 'body', dc: 35, win: 'It was done. Later you learned the elder had been blackmailing the client’s daughter for years. Or so the client said.', pay: { wealth: 35 }, inf: 6, san: -8,
    alt: R('Investigate the client first', 'insight', 35, O('You dug into the client and found the elder innocent and the client a jealous rival. You returned the fee and told the elder to watch his back.', { rep: { orthodox: 3 }, insight: 2, sanity: 4 }), O('You dug, found nothing either way, and could not strike on nothing. The contract lapsed.', { merit: -5 })) },
  { key: 'bandit_chief', if: { region: ['hebei', 'jingchu'] }, text: 'A Green Forest chief who raids beyond the Green Forest’s own rules is the mark. The client is, surprisingly, another Green Forest chief.',
    go: 'Take the chief’s head', stat: 'power', dc: 35, win: 'You took the chief in his own hall. The Green Forest called it an internal matter and paid without complaint.', pay: { wealth: 30, rep: { unorthodox: 4 }, merit: 10 }, inf: 3, san: -4,
    alt: C('Challenge him to a public duel instead', O('You called him out before the strongholds.', { combat: { foe: { name: 'the rule-breaking chief', kind: 'bandit', rel: 0.5 }, context: 'duel', lethal: 0.4, win: { text: 'He fell, honourably, and the Green Forest nodded.', wealth: 30, rep: { unorthodox: 6 }, fame: 2 }, lose: { text: 'He was better than the client said. You barely crawled away.', health: -20 } } })) },
  { key: 'depot_torturer', if: { region: ['hebei', 'central'] }, text: 'An Eastern Depot interrogator is the mark. Half the murim would pay for this one. The client is a Beggars’ Sect elder who speaks for all of them.',
    go: 'End the interrogator', stat: 'body', dc: 38, win: 'The Depot lost its most feared man and never admitted it. The Beggars sent you a feast you could not finish.', pay: { wealth: 20, rep: { court: -8, orthodox: 6 }, merit: 15 }, inf: 2, san: -5,
    alt: R('Free his prisoners instead', 'body', 36, O('You went for the cells, not the man. Nine prisoners walked free, and the interrogator had nothing left to interrogate.', { fame: 5, rep: { court: -6 }, merit: 10 }), O('The cells were a trap. You left with nothing but a Depot black mark against your name.', { infamy: 3, rep: { court: -4 } })) },
  { key: 'faithless_lover', if: { region: ['jiangnan', 'shu', 'central'] }, text: 'A jilted noble wants their faithless lover dead. It is the pettiest contract you have been offered, and the fee is the largest.',
    go: 'Take the petty contract', stat: 'insight', dc: 30, win: 'You did the petty thing for the large fee. The noble wept with gratitude, which somehow made it worse.', pay: { wealth: 60 }, inf: 6, san: -14,
    alt: C('Refuse and return the fee', O('You gave the fee back and told the noble to grow up. The Pavilion docked your standing for turning down silver. You slept fine.', { merit: -8, sanity: 6 })) },
  { key: 'poison_scholar', if: { or: [{ path: 'poison' }, { sect: 'dang' }] }, text: 'The contract calls for a scholar to die slowly of a wasting illness, so no blade is suspected. You are chosen for your knowledge of poisons.',
    go: 'Accept the poison contract', stat: 'insight', dc: 35, win: 'The scholar faded over a season and the physicians called it consumption. You have never felt less like a healer.', pay: { wealth: 45 }, inf: 5, san: -12,
    alt: C('Give him a cure and bill the client for a poison', O('You slipped the scholar a tonic instead and told the client the slow illness had begun. By the time the client noticed, you were three provinces away.', { wealth: 45, flag: 'cr.double_cross', sanity: 2 })) },
  { key: 'child_heir', if: { region: ['jiangnan', 'hebei'] }, text: 'The mark is a child, the heir to an estate an uncle wants. This is the contract that tells an assassin who they are.',
    go: 'Refuse it loudly, and remember the uncle', stat: 'charm', dc: 1, win: 'You refused, and made sure the Pavilion knew why. Nameless tore the contract up herself; she never takes one on a child. The uncle you remembered for another day.', pay: { merit: 5, sanity: 8, rep: { orthodox: 2 } }, inf: 0, san: 0,
    alt: C('Carry the contract to the child’s guardians', O('You brought the contract to the estate’s steward. The uncle fled; the child never knew how close it came. You were paid in a night’s good sleep.', { fame: 2, sanity: 6 })) },
], (r) => E('cr_contract', 'crime', { if: { ...BLADE, age: [16, 70], ...(r.if || {}) }, once: false, cd: 4, danger: true, art: 'night', title: 'A contract', text: r.text, choices: [
  R(r.go, r.stat, r.dc, O(r.win, { ...r.pay, infamy: r.inf, sanity: r.san }), O('It went wrong. Someone talked, or someone was waiting. You walked it back with nothing but a scar.', { infamy: Math.ceil(r.inf / 2) || 1, health: -8 })),
  r.alt,
  C('Return the slip unopened', O('You handed the slip back without reading it. The broker shrugged; there is always another knife.', { merit: -2 })),
] }));

// ── Template: protection rackets, one per target ───────────────────────────────────────────
const tplExtort = template('cr_extort', [
  { key: 'teahouse', if: { locType: 'city' }, text: 'A teahouse on the busiest corner in town does well and pays nobody for the privilege. The owner is a widow with three sons at the front.',
    go: 'Lean on the widow', stat: 'charm', dc: 20, win: 'She paid, monthly, and hated you politely over free tea you did not want.', pay: { wealth: 10 }, inf: 2, alt: C('Offer real protection instead', O('You ran off the drunks and the dine-and-dash crowd for an honest cut, and she started saving your table.', { wealth: 6, fame: 1, sanity: 2 })) },
  { key: 'gambling_den', if: { locType: 'city' }, text: 'A gambling den has opened on your crew’s turf without asking anyone. The man who runs it is new in town and does not yet know whose town it is.',
    go: 'Explain whose town it is', stat: 'power', dc: 25, win: 'He understood quickly, the way people do when a sword is on the table. The den pays a cut now, grudgingly.', pay: { wealth: 15 }, inf: 2, alt: R('Win the den off him at his own tables', 'insight', 35, O('You played his crooked games better than he did and owned the den by dawn, legally, more or less.', { wealth: 20, flag: 'cr.owns_den' }), O('His games were more crooked than you were clever.', { wealth: -15 })) },
  { key: 'salt_road', if: { region: ['jingchu', 'central'] }, text: 'Salt traders cross your stretch of road twice a month, heavy with coin on the way home. A "road maintenance fee" would hardly be noticed, you tell yourself.',
    go: 'Set up a toll', stat: 'power', dc: 28, win: 'The traders paid the toll and built it into their prices, and the townsfolk at the end of the road paid for your boots.', pay: { wealth: 18 }, inf: 3, alt: C('Guard the road for a fair wage instead', O('You offered the traders real escort against the real bandits, for a fair fee. They took it, and the bandits took the hint.', { wealth: 12, fame: 2 })) },
  { key: 'brothel', if: { locType: 'city' }, text: 'A pleasure house pays the local constables and nobody else. Your crew would like to be somebody else. The madam is no fool.',
    go: 'Negotiate a cut', stat: 'charm', dc: 25, win: 'The madam paid, on condition you kept the rough trade out. You found you were good at it, and she found you cheaper than the constables.', pay: { wealth: 14 }, inf: 2, alt: C('Take the women’s complaints to the magistrate', O('You carried the house’s grievances to an honest magistrate. The constables lost a bribe and the house gained a day off. Your crew never understood why.', { fame: 2, sanity: 4, rep: { court: 2 } })) },
  { key: 'festival', if: { locType: ['city', 'village'] }, text: 'The spring festival fills the market with stalls, and stalls with coin. Every petty crew in the province will be shaking down vendors tonight.',
    go: 'Work the festival', stat: 'body', dc: 22, win: 'You worked the crowd and the stalls and came home heavy. The festival ended, as it always does, with someone crying.', pay: { wealth: 20 }, inf: 3, alt: R('Run the other crews off instead', 'power', 30, O('You chased every other shakedown crew out of the market and let the vendors keep their coin. They called you the festival’s luck.', { fame: 4, rep: { unorthodox: -4 } }), O('The other crews had numbers. You had a bad night and a reputation dent.', { health: -10 })) },
  { key: 'guild_office', if: { region: ['jiangnan'], locType: 'city' }, text: 'The Golden Abacus Guild’s local office is wealthy, well-guarded, and insured against exactly this. Shaking it down is ambitious bordering on suicidal.',
    go: 'Shake down the Guild office', stat: 'insight', dc: 38, win: 'You found the ledger that mattered and asked a modest monthly sum to keep it quiet. The Guild paid, and put a price on your head the same day.', pay: { wealth: 25, rep: { merchants: -8 } }, inf: 4, alt: C('Sell the ledger to a Guild rival instead', O('A rival house paid well for the Guild’s dirty ledger and asked you to leave the province, warmly.', { wealth: 30, rep: { merchants: -4 } })) },
  { key: 'monastery', if: { locType: ['village', 'sect'] }, text: 'A small mountain monastery collects pilgrims’ donations. Your crew thinks monks are soft. You are not certain the crew has met many monks.',
    go: 'Demand a donation of your own', stat: 'power', dc: 30, win: 'The abbot gave you rice and a blessing you did not ask for, and somehow you came away feeling you had been the one shaken down.', pay: { wealth: 6, sanity: -4 }, inf: 2, alt: C('Ask for a bowl of rice and leave', O('You asked only for a meal. The abbot fed you and said you were welcome back, which you found you meant to be.', { sanity: 5, rep: { orthodox: 1 } })) },
  { key: 'dockyard', if: { region: ['jingchu', 'jiangnan'], locType: 'city' }, text: 'The river dockyard runs on muscle and bad pay, and the foreman skims the wages. A crew that controlled the dock would control the wages too.',
    go: 'Take over the dock rackets', stat: 'power', dc: 32, win: 'You ran off the foreman’s thugs and became the dock’s new tax. The dockers traded one leech for another and said so to your face.', pay: { wealth: 16 }, inf: 3, alt: R('Organise the dockers against the foreman', 'charm', 35, O('You talked the dockers into downing tools until the foreman paid full wages. They named a mooring after you.', { fame: 4, sanity: 4, rep: { merchants: -3 } }), O('The foreman’s thugs broke the strike and your nose.', { health: -12 })) },
  { key: 'pawnbroker', if: { locType: ['city', 'village'] }, text: 'The town pawnbroker lends at ruinous rates to desperate people and keeps a strongbox under the counter. Robbing him would be a kindness to half the county.',
    go: 'Demand a share of the strongbox', stat: 'power', dc: 26, win: 'He paid, and you noticed he passed the cost straight to the desperate. Crime, you are learning, mostly flows downhill.', pay: { wealth: 14, sanity: -3 }, inf: 2, alt: C('Burn the debt slips of the poorest instead', O('You took the strongbox’s worst debt slips and burned them in the square. A dozen families slept easier; the pawnbroker did not.', { fame: 3, sanity: 5 })) },
  { key: 'actors', if: { locType: 'city' }, text: 'A travelling opera troupe has the whole town’s coin for a week. Troupes are easy marks: they cannot stay and they cannot fight. The lead actress looks at you without the usual fear.',
    go: 'Demand a cut of the gate', stat: 'charm', dc: 24, win: 'They paid, and put a villain in that night’s play who walked exactly like you. The crowd loved it. You did not.', pay: { wealth: 12 }, inf: 1, alt: C('Buy the whole house a performance instead', O('You paid the troupe’s gate yourself and let the town watch free. The lead actress found you afterwards, curious why. You did not have a good answer.', { wealth: -10, fame: 2, sanity: 4 })) },
], (r) => E('cr_extort', 'crime', { if: { ...DARK, age: [14, 60], ...(r.if || {}) }, once: false, cd: 4, art: 'market', title: 'A racket', text: r.text, choices: [
  R(r.go, r.stat, r.dc, O(r.win, { ...r.pay, infamy: r.inf }), O('It went sideways. The mark had friends, or nerve, and you left empty-handed and marked.', { infamy: r.inf, health: -5 })),
  r.alt,
  C('Leave them be', O('You left them be. Not every corner has to be somebody’s.', { sanity: 1 })),
] }));

// ── Template: the Ghost Market's wares, one per lot (needs the token) ──────────────────────
const tplWares = template('cr_wares', [
  { key: 'ghost_step', text: 'A seller with no shadow offers the Ghost Shadow Step, "lifted from a Green Forest corpse, barely used."', req: { wealth: '>=70', noManual: 'uno_ghost_step' }, price: 70, win: 'The manual was genuine, and the steps came to you like old habits.', fx: { manual: 'uno_ghost_step', infamy: 2 }, risk: 0.15, bad: 'The pages past the third were blank. You had bought half a manual at full price.' },
  { key: 'five_venoms', text: 'A pock-faced woman sells the Five Venoms Palm, "complete, with the counter-poisons, which is more than the Dang will sell you."', req: { wealth: '>=90', noManual: 'med_five_venoms' }, price: 90, win: 'Complete, and the counter-poisons worked, which you tested carefully.', fx: { manual: 'med_five_venoms', infamy: 2, rep: { families: -3 } }, risk: 0.2, bad: 'The counter-poisons were chalk. You learned the palm and spent a month not touching your own face.' },
  { key: 'reincarnation', text: 'Wrapped in wax and lies: a Small Reincarnation Pill, "fallen off a Shaolin cart, swear on my mother."', req: { wealth: '>=200' }, price: 200, win: 'It was real. A decade of cultivation went down your throat in one swallow, and Shaolin is short one pill.', fx: { item: { reincarnation_pill: 1 }, infamy: 2, rep: { orthodox: -4 } }, risk: 0.35, bad: 'It was a Qi-Gathering Pill in expensive wax. You paid a fortune for a week of warm dantian.' },
  { key: 'snow_lotus', text: 'A frostbitten trader offers a Heavenly Mountain Snow Lotus, "picked on Kunlun, do not ask how I got down."', req: { wealth: '>=150', noItem: 'snow_lotus' }, price: 150, win: 'The lotus was real, its petals still cold to the touch in the summer heat.', fx: { item: { snow_lotus: 1 } }, risk: 0.2, bad: 'A white silk flower, cleverly chilled. You bought it because you wanted to believe.' },
  { key: 'alliance_seal', text: 'Under a cloth, a Murim Alliance elder’s seal, "for letters you want believed."', req: { wealth: '>=60' }, price: 60, win: 'A seal good enough to be real. Doors in the Orthodox world will open to paper you stamp with it.', fx: { flag: 'cr.alliance_seal', infamy: 3 }, risk: 0.25, bad: 'The seal was a crude fake. The first clerk who saw it laughed, then reached for a bell.' },
  { key: 'map_hoard', text: 'A one-eyed cartographer sells a map to a hermit’s unlooted cave hoard, "and the hermit is thirty years dead, so he won’t mind."', req: { wealth: '>=40' }, price: 40, win: 'The map led to a dry cave and a chest of a dead hermit’s silver. You left his bones as you found them.', fx: { wealth: 80, sanity: -2 }, risk: 0.4, bad: 'The cave was real, and empty, and someone had got there first. You bought a long walk.' },
  { key: 'antidote', text: 'A nervous man sells the one recipe for an antidote the Dang family guards closely, "in case you ever cross them. Everyone crosses them eventually."', req: { wealth: '>=50' }, price: 50, win: 'You will never know if it works until you need it, which is the worst kind of purchase. The recipe copied with it rang true.', fx: { recipe: 'yang_cure', infamy: 1 }, risk: 0.2, bad: 'The recipe was for a cough tonic. You hope you never find out the hard way.' },
  { key: 'tiger_bone', text: 'A hunter sells the Tiger Bone Tempering, an external body art, "written on real tiger hide, feel that."', req: { wealth: '>=65', noManual: 'ext_tiger_bone' }, price: 65, win: 'The hide was real and so was the art. Your bones ached for a month and then stopped breaking.', fx: { manual: 'ext_tiger_bone', infamy: 1 }, risk: 0.15, bad: 'Goat hide, and a beginner’s stretching routine copied in a child’s hand.' },
  { key: 'court_roster', text: 'A sweating clerk sells the Eastern Depot’s roster of agents in the Central Plains, "worth your life if they find me, so pay what it’s worth."', req: { wealth: '>=120' }, price: 120, win: 'Names, faces and teahouses. Knowing a Depot agent on sight is worth more than any blade.', fx: { codex: { id: 'secret.cr_depot_roster', cat: 'secrets', title: 'The Depot’s agents', text: 'A Ghost Market list of Eastern Depot agents in the Central Plains: the "fruit seller" at Luoyang’s east gate, the physician on Kaifeng’s Willow Lane, and the blind erhu player outside the Alliance hall.' }, infamy: 2, rep: { court: -3 } }, risk: 0.3, bad: 'Half the names were of people three years dead. The clerk was long gone when you checked.' },
  { key: 'wheel_bead', if: { mem: 'timeline.red_sky' }, text: 'An old woman at the last stall holds out a cracked black bead on a string. "You keep looking for this one," she says, though you have never met. "No charge. You always come back for it."', req: { wealth: '>=1' }, price: 0, win: 'The bead was warm in your hand, and it should not have been. You have held it before. You are sure of it.', fx: { item: { wheel_bead: 1 }, sanity: -3, gaze: 1 }, risk: 0, bad: '' },
], (r) => E('cr_wares', 'crime', { if: { flag: 'cr.gm_token', loc: 'kaifeng', age: [14, 90], ...(r.if || {}) }, once: false, cd: 2, art: 'market', title: 'A Ghost Market lot', text: r.text, choices: [
  r.risk > 0
    ? QP(`Buy it (${r.price} taels)`, r.req, 1 - r.risk, O(r.win, { wealth: -r.price, ...r.fx }), O(r.bad, { wealth: -r.price, sanity: -2 }))
    : Q(`Take it (${r.price} taels)`, r.req, O(r.win, { wealth: -r.price, ...r.fx })),
  R('Haggle, and walk if the price holds', 'charm', 30, O('You haggled the seller down, bought nothing, and left them respecting you and poorer in spirit.', { charm: 1 }), O('The seller held firm; you left with your coin and your curiosity both intact.')),
  C('Just look', O('You looked, and filed the stall away in memory. In the Ghost Market, knowing what is for sale is half the trade.', { insight: 1 })),
] }));

// ── Template: framing and being framed, one per faction ────────────────────────────────────
const tplFrame = template('cr_frame', [
  { key: 'orthodox', if: { faction: 'orthodox', rank: [0, 2] }, text: 'Evidence has appeared that you stole from the sect treasury: a witness, a hidden purse, a note in a hand very like yours. You did not do it. Someone wants your place.',
    clear: 'Unpick the frame', stat: 'insight', dc: 32, cleared: 'You traced the forged note to the senior who wanted your place, and laid it before the elders. He left in disgrace; you did not gloat, much.', clearFx: { rep: { orthodox: 5 }, merit: 10, flag: 'cr.cleared' }, caught: 'The elders believed the evidence. You were expelled, your name struck from the register.', caughtFx: { expel: true, infamy: 3 },
    bribe: Q('Pay the witness to recant (30 taels)', { wealth: '>=30' }, O('Thirty taels bought the witness a sudden attack of honesty. The charge collapsed, and you learned which friends were not.', { wealth: -30, flag: 'cr.cleared' })) },
  { key: 'court', if: { region: ['hebei', 'central'] }, text: 'The Eastern Depot has decided you are a Cult spy. The evidence is a letter you never wrote, in red Cult ink, found in your room by the men who put it there.',
    clear: 'Prove the letter a forgery', stat: 'insight', dc: 40, cleared: 'You showed the censor that the Cult ink was the Depot’s own, from the Depot’s own stores. The censor could not ignore it. The Depot could not forgive it.', clearFx: { rep: { court: -5, orthodox: 4 }, flag: 'cr.cleared', fame: 2 }, caught: 'The Depot does not need to convince anyone. You fled north with a price on your head.', caughtFx: { infamy: 5, travel: 'luoyang', next: 'cr_hunter.depot_constable' },
    bribe: Q('Buy a censor’s intervention (80 taels)', { wealth: '>=80' }, O('Eighty taels bought a censor who outranked the Depot’s man. The charge vanished, and so did your savings.', { wealth: -80, flag: 'cr.cleared' })) },
  { key: 'families', if: { region: ['jiangnan', 'hebei'], faction: ['families', 'none'] }, text: 'A Great Family has blamed you for a theft from their vaults, loudly and in public. They do not care whether you did it; they care that a stranger is blamed.',
    clear: 'Find the real thief', stat: 'insight', dc: 35, cleared: 'You found the real thief, a cousin with debts, and handed the family their own blood. They thanked you coldly and will never speak of it.', clearFx: { rep: { families: 4 }, flag: 'cr.cleared', insight: 2 }, caught: 'The family’s word is law in their province. You were run out of it with their men at your heels.', caughtFx: { infamy: 4, rep: { families: -10 } },
    bribe: C('Let a rival family take your side', O('A rival house, delighted to embarrass the accusers, leapt to your defence. You are cleared, and now a pawn in a feud older than you.', { flag: 'cr.cleared', rep: { families: -2 } })) },
  { key: 'unorthodox', if: { faction: 'unorthodox' }, text: 'Someone in your own faction has told the boss you skimmed the take. In the Black Path, a thief who steals from thieves does not get a trial.',
    clear: 'Show the real skimmer’s hand', stat: 'insight', dc: 30, cleared: 'You showed the boss whose fingers were really in the take. The accuser met the end meant for you, and you got his share.', clearFx: { wealth: 20, merit: 8, flag: 'cr.cleared', infamy: 2 }, caught: 'The boss believed the accuser. You ran from your own brothers, which is the loneliest running there is.', caughtFx: { infamy: 3, leave: true, sanity: -8 },
    bribe: C('Fight the accuser before the boss', O('You called the accuser out in the hall. The boss let steel decide it, which in the Black Path is the fairest trial there is.', { combat: { foe: { name: 'the lying brother', kind: 'bandit', rel: 0 }, context: 'duel', lethal: 0.3, win: { text: 'He fell, and his lie with him. The boss poured you a drink.', flag: 'cr.cleared', merit: 6 }, lose: { text: 'He was better than you, which the hall took as proof of his innocence. You crawled out an outcast.', leave: true, infamy: 2 } } })) },
  { key: 'merchants', if: { region: ['jiangnan'], locType: 'city' }, text: 'A merchant you crossed has had you charged with passing counterfeit silver. The counterfeits were real; he minted them and slipped them to you himself.',
    clear: 'Trace the counterfeits to the mint', stat: 'insight', dc: 34, cleared: 'You followed the bad silver back to the merchant’s own cellar, and the magistrate followed you. The merchant minted his last coin in a cell.', clearFx: { rep: { merchants: 3 }, flag: 'cr.cleared', fame: 2 }, caught: 'The merchant had the magistrate’s ear and your hands in the till. You took a season breaking rocks.', caughtFx: { infamy: 3, next: 'cr_prison.hangzhou' },
    bribe: Q('Hire a better advocate (40 taels)', { wealth: '>=40' }, O('A clever advocate turned the merchant’s own witnesses against him. Justice, you are learning, has a price list.', { wealth: -40, flag: 'cr.cleared' })) },
  { key: 'you_frame', if: { stat: { insight: '>=25' } }, text: 'You have an enemy you cannot beat in the open, but you can beat with a brush: a forged letter, a planted purse, a whisper in the right ear. The dark path cuts both ways.',
    clear: 'Frame your enemy', stat: 'insight', dc: 30, cleared: 'Your enemy fell for a crime that was yours to invent. It worked beautifully, and you have not met your own eyes in a mirror since.', clearFx: { infamy: 2, sanity: -8, flag: 'cr.framer' }, caught: 'Your forgery was one flourish too clever. It was traced back, and your enemy added "liar" to the list of things they call you.', caughtFx: { infamy: 4, sanity: -4 },
    bribe: C('Beat them honestly instead, somehow', O('You put the brush down and found another way: slower, harder, and one you can live with. Your enemy never knew how close they came to ruin.', { sanity: 6, insight: 1 })) },
], (r) => E('cr_frame', 'crime', { if: { age: [16, 70], ...r.if }, once: false, cd: 8, danger: true, art: 'scroll', title: r.key === 'you_frame' ? 'A brush, not a blade' : 'Framed', text: r.text, choices: [
  R(r.clear, r.stat, r.dc, O(r.cleared, r.clearFx), O(r.caught, r.caughtFx)),
  r.bribe,
  r.key === 'you_frame'
    ? C('Leave them be', O('You left your enemy standing. Some victories are not worth what they cost to win.', { sanity: 3 }))
    : C('Run rather than fight it', O('You did not wait for a verdict. You were gone by the next tide, name and all, to start again as someone new.', { infamy: 2, sanity: -4 })),
] }));

export default [
  ...handwritten,
  ...tplPrison, ...tplHeist, ...tplSmuggle, ...tplHunter, ...tplDen,
  ...tplContract, ...tplExtort, ...tplWares, ...tplFrame,
];
